  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{};
  float phase = 0, spin = 0, wobble = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    phase = rng.unit() * 10.0f;
    spin = rng.unit();
    wobble = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 14.0f, 3.5f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 8.0f, 2.0f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    kick = std::max(kick * std::exp(-dt * 6.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 18.0f, 4.0f, dt);
    }

    phase += dt * f.speed * (0.3f + 1.2f * drive + 1.0f * kick);
    spin += dt * f.speed * (0.008f + 0.035f * drive + 0.06f * kick);
    wobble += dt * f.speed * (0.6f + 2.0f * body);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float spikes = std::round(18.0f + 8.0f * f.detail);
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {phase, spin, 0.19f + 0.015f * bass * amp, spikes});
    u.insert(u.end(), {0.05f, 0.14f * bass * amp, 0.14f * amp, kick * amp});
    u.insert(u.end(), {wobble, body, drive, 0.0f});
    u.insert(u.end(), {bands[0], bands[1], bands[2], bands[3]});
    u.insert(u.end(), {bands[4], bands[5], bands[6], bands[7]});
    u.insert(u.end(), {spark, flash, f.glow, energy});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("ferro", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.ferro:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;      // tiempo, giro, radio de la cúpula, número de púas
uniform vec4 uB;      // púa base, púa por graves, púa por banda, golpe
uniform vec4 uW;      // ondulación, medios, impulso, libre
uniform vec4 uBands0;
uniform vec4 uBands1;
uniform vec4 uL;      // agudos, destello, glow, energía
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float pick(float i) {
  if (i < 0.5) return uBands0.x;
  if (i < 1.5) return uBands0.y;
  if (i < 2.5) return uBands0.z;
  if (i < 3.5) return uBands0.w;
  if (i < 4.5) return uBands1.x;
  if (i < 5.5) return uBands1.y;
  if (i < 6.5) return uBands1.z;
  return uBands1.w;
}

// Banda por dirección: graves arriba, agudos abajo, simétrico.
float bandAt(float turns) {
  float m = abs(fract(turns + 0.25) * 2.0 - 1.0) * 7.0;
  float i = floor(m);
  return mix(pick(i), pick(min(i + 1.0, 7.0)), smoothstep(0.0, 1.0, m - i));
}

float spikeLength(float turns) {
  float wave = 0.5 + 0.5 * sin(turns * 6.2831853 * 3.0 - uA.x * 1.7);
  float wave2 = 0.5 + 0.5 * sin(turns * 6.2831853 * 5.0 + uA.x * 1.1);
  return uB.x * (0.6 + 0.8 * wave * wave2) + uB.y * (0.7 + 0.3 * wave) +
         bandAt(turns) * uB.z + uB.w * (0.07 + 0.05 * wave2);
}

// Cono de sección redonda que nace del borde de la cúpula y se afila.
float spike(float r, float a, float offset, float scale) {
  float n = uA.w;
  float aa = a + offset;
  float k = floor(aa);
  float f = aa - k - 0.5;
  float len = spikeLength((k + 0.5 - offset) / n - uA.y) * scale;
  float base = uA.z * 0.80;
  float t = (r - base) / (len + uA.z * 0.22);
  float halfW = 0.5 * (1.0 - t);
  float d = abs(f) / max(halfW, 0.0001);
  float inside = step(0.0, t) * step(t, 1.0) * step(d, 1.0);
  return inside * uA.z * 0.66 * pow(max(1.0 - t, 0.0), 1.15) *
         sqrt(max(1.0 - d * d, 0.0));
}

float height(vec2 p) {
  float r = length(p);
  float a = (atan(p.y, p.x) / 6.2831853 + uA.y) * uA.w;
  float breathe = 1.0 + 0.02 * sin(uW.x + r * 30.0) + 0.05 * uB.w;
  float dr = r / (uA.z * breathe);
  float dome = uA.z * sqrt(max(1.0 - dr * dr, 0.0));
  float s = max(spike(r, a, 0.0, 1.0), spike(r, a, 0.5, 0.55));
  // Unión suave entre cúpula y púas.
  if (dome <= 0.0 || s <= 0.0) return max(dome, s);
  float k = uA.z * 0.08;
  float hk = clamp(0.5 + 0.5 * (s - dome) / k, 0.0, 1.0);
  return mix(dome, s, hk) + k * hk * (1.0 - hk);
}

vec3 environment(vec3 r) {
  float kick = uB.w;
  vec3 col = uC0 * 0.25;
  float up = step(0.0, r.z);
  // Softbox redondeado y difuso arriba a la izquierda, más brillante arriba.
  vec2 q = r.xy - vec2(-0.30, 0.36);
  vec2 bq = abs(q) - vec2(0.17, 0.10);
  float box = length(max(bq, 0.0)) + min(max(bq.x, bq.y), 0.0) - 0.06;
  float soft = (1.0 - smoothstep(-0.06, 0.10, box)) * (0.65 + 0.35 * smoothstep(-0.2, 0.2, q.y));
  col += vec3(1.0, 0.97, 0.94) * soft * (1.3 + 3.0 * uL.y + 1.0 * kick) * up;
  // Luz de relleno cálida, pequeña y muy suave abajo a la derecha.
  float fill = exp(-dot(r.xy - vec2(0.45, -0.35), r.xy - vec2(0.45, -0.35)) * 18.0);
  col += uC3 * fill * 0.35 * up;
  // Luces de color en el horizonte: sólo las ven los flancos rasantes.
  float az = atan(r.y, r.x);
  float horizon = pow(1.0 - abs(r.z), 5.0);
  vec3 rim = mix(uC1, uC2, smoothstep(-0.6, 0.6, sin(az + uA.x * 0.25)));
  col += rim * horizon * (1.4 + 3.5 * kick + 1.2 * uL.w) * uL.z;
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float r0 = length(p);
  float kick = uB.w;

  // Fondo: estudio oscuro con halo de color que late con el golpe.
  float halo = exp(-r0 * r0 * 7.0);
  vec3 bg = uC0 + mix(uC1, uC2, 0.5 + 0.5 * sin(atan(p.y, p.x) + uA.x * 0.3)) *
            halo * (0.10 + 0.45 * kick + 0.15 * uL.w) * uL.z;
  float rings = 0.5 + 0.5 * sin(r0 * 60.0 - uA.x * 4.0);
  bg += mix(uC2, uC1, 0.5) * halo * rings * (0.015 + 0.08 * kick);
  vec3 col = bg;

  float h0 = height(p);
  if (h0 > 0.0) {
    float e = 1.25 / scale;
    float hx = height(p + vec2(e, 0.0));
    float hy = height(p + vec2(0.0, e));
    vec3 n = normalize(vec3(-(hx - h0) / e, -(hy - h0) / e, 1.0));
    vec3 v = vec3(0.0, 0.0, 1.0);
    vec3 r = reflect(-v, n);
    float fres = 0.05 + 0.95 * pow(1.0 - max(n.z, 0.0), 5.0);
    vec3 surf = environment(r) * (0.25 + 0.75 * fres);
    // Brillos con los agudos en las puntas de las púas.
    float tip = smoothstep(0.03, 0.0, h0) * step(uA.z * 1.05, r0);
    float tw = hash12(floor(vec2(atan(p.y, p.x) * uA.w * 0.5, uA.x * 8.0)));
    surf += uC3 * tip * smoothstep(0.4, 1.0, tw) * uL.x * 3.0;
    // Contorno suave para evitar dientes de sierra en el borde.
    float edge = smoothstep(0.0, 0.004, h0);
    col = mix(bg * 0.4, surf, edge);
  }

  col *= 1.0 - 0.4 * smoothstep(0.35, 1.2, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.shaderSource:
vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float r = length(p);
  float a = getAngle(p);

  float beat = clamp(f.pulse, 0.0, 1.0);
  float bass = clamp(f.bass, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);
  float t = f.time * 0.42 * f.speed;

  // Background deep sacred cosmic aura
  vec3 bgCol = mix(vec3(0.02, 0.008, 0.06), vec3(0.06, 0.015, 0.14), r * 0.8);
  bgCol = bgCol + vec3(0.1, 0.02, 0.18) * sin(r * 4.0 - t * 1.5) * 0.3;

  vec3 col = bgCol;

  // Fibonacci Petal Ring 1 (Inner 5 petals)
  float a1 = a + t * 0.6;
  float pet1 = cos(5.0 * a1);
  float r1 = 0.18 + 0.08 * pet1 + bass * 0.06;
  float d1 = abs(r - r1);
  float edge1 = 0.012 / (d1 + 0.012);
  vec3 col1 = mix(vec3(1.0, 0.85, 0.2), vec3(1.0, 0.25, 0.6), 0.5 + 0.5 * pet1);
  col = col + col1 * edge1 * 0.7;

  // Fibonacci Petal Ring 2 (Middle 8 petals, counter-rotating)
  float a2 = a - t * 0.4;
  float pet2 = cos(8.0 * a2);
  float r2 = 0.35 + 0.12 * pet2 + beat * 0.08;
  float d2 = abs(r - r2);
  float edge2 = 0.015 / (d2 + 0.018);
  vec3 col2 = mix(vec3(0.2, 0.85, 1.0), vec3(0.9, 0.1, 0.7), 0.5 + 0.5 * pet2);
  col = col + col2 * edge2 * 0.65;

  // Fibonacci Petal Ring 3 (Outer 13 petals)
  float a3 = a + t * 0.25;
  float pet3 = cos(13.0 * a3);
  float r3 = 0.58 + 0.15 * pet3 + bass * 0.1;
  float d3 = abs(r - r3);
  float edge3 = 0.018 / (d3 + 0.022);
  vec3 col3 = mix(vec3(0.95, 0.3, 0.8), vec3(1.0, 0.7, 0.2), 0.5 + 0.5 * pet3);
  col = col + col3 * edge3 * 0.6;

  // Fibonacci Petal Ring 4 (Ethereal 21 filaments)
  float a4 = a - t * 0.15;
  float pet4 = cos(21.0 * a4);
  float r4 = 0.82 + 0.14 * pet4 + beat * 0.06;
  float d4 = abs(r - r4);
  float edge4 = 0.012 / (d4 + 0.025);
  vec3 col4 = mix(vec3(0.4, 0.3, 1.0), vec3(0.2, 0.95, 0.8), 0.5 + 0.5 * pet4);
  col = col + col4 * edge4 * (0.4 + 0.3 * spark);

  // Sacred golden spiral rays
  float spiral1 = sin(log(r + 0.02) * 5.0 - a * 3.0 + t * 1.2);
  float spiral2 = sin(log(r + 0.02) * 5.0 + a * 3.0 - t * 1.2);
  float spiralGrid = smoothstep(0.85, 0.98, spiral1) + smoothstep(0.85, 0.98, spiral2);
  col = col + vec3(1.0, 0.8, 0.3) * spiralGrid * 0.35 * exp(-r * 1.8);

  // Radiant Golden Core / Lotus Stamen
  float coreDist = r;
  float coreGlow = 0.04 / (coreDist * coreDist * 6.0 + 0.04);
  float corePulse = 1.0 + 0.4 * sin(t * 4.0) + bass * 0.8;
  vec3 coreColor = mix(vec3(1.0, 0.95, 0.5), vec3(1.0, 0.4, 0.1), clamp(r * 5.0, 0.0, 1.0));
  col = col + coreColor * coreGlow * corePulse * 1.2;

  // Stardust / Pollen particles swirling around the flower
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float pAngle = fi * 1.047 + t * (0.8 + 0.2 * fi);
    float pRad = 0.25 + 0.15 * sin(fi * 2.1 + t * 1.5) + bass * 0.1;
    vec2 pPos = vec2(cos(pAngle), sin(pAngle)) * pRad;
    float pDist = length(p - pPos);
    float pGlow = 0.003 / (pDist * pDist * 25.0 + 0.003);
    col = col + vec3(1.0, 0.9, 0.4) * pGlow * (0.8 + 0.8 * spark);
  }

  // Soft tone mapping and cinematic vignette
  col = col / (col + vec3(0.85));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  return vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float r = length(p);
  float a = getAngle(p);

  float beat = clamp(f.pulse, 0.0, 1.0);
  float bass = clamp(f.bass, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);
  float t = f.time * 0.42 * f.speed;

  vec3 col = vec3(0.0);

  // Fibonacci Petal Ring 1 (Inner 5 petals)
  float a1 = a + t * 0.6;
  float pet1 = cos(5.0 * a1);
  float r1 = 0.18 + 0.08 * pet1 + bass * 0.06;
  float d1 = abs(r - r1);
  float edge1 = 0.012 / (d1 + 0.012);
  vec3 col1 = mix(vec3(1.0, 0.85, 0.2), vec3(1.0, 0.25, 0.6), 0.5 + 0.5 * pet1);
  col = col + col1 * edge1 * 0.7;

  // Fibonacci Petal Ring 2 (Middle 8 petals, counter-rotating)
  float a2 = a - t * 0.4;
  float pet2 = cos(8.0 * a2);
  float r2 = 0.35 + 0.12 * pet2 + beat * 0.08;
  float d2 = abs(r - r2);
  float edge2 = 0.015 / (d2 + 0.018);
  vec3 col2 = mix(vec3(0.2, 0.85, 1.0), vec3(0.9, 0.1, 0.7), 0.5 + 0.5 * pet2);
  col = col + col2 * edge2 * 0.65;

  // Fibonacci Petal Ring 3 (Outer 13 petals)
  float a3 = a + t * 0.25;
  float pet3 = cos(13.0 * a3);
  float r3 = 0.58 + 0.15 * pet3 + bass * 0.1;
  float d3 = abs(r - r3);
  float edge3 = 0.018 / (d3 + 0.022);
  vec3 col3 = mix(vec3(0.95, 0.3, 0.8), vec3(1.0, 0.7, 0.2), 0.5 + 0.5 * pet3);
  col = col + col3 * edge3 * 0.6;

  // Fibonacci Petal Ring 4 (Ethereal 21 filaments)
  float a4 = a - t * 0.15;
  float pet4 = cos(21.0 * a4);
  float r4 = 0.82 + 0.14 * pet4 + beat * 0.06;
  float d4 = abs(r - r4);
  float edge4 = 0.012 / (d4 + 0.025);
  vec3 col4 = mix(vec3(0.4, 0.3, 1.0), vec3(0.2, 0.95, 0.8), 0.5 + 0.5 * pet4);
  col = col + col4 * edge4 * (0.4 + 0.3 * spark);

  // Sacred golden spiral rays
  float spiral1 = sin(log(r + 0.02) * 5.0 - a * 3.0 + t * 1.2);
  float spiral2 = sin(log(r + 0.02) * 5.0 + a * 3.0 - t * 1.2);
  float spiralGrid = smoothstep(0.85, 0.98, spiral1) + smoothstep(0.85, 0.98, spiral2);
  col = col + vec3(1.0, 0.8, 0.3) * spiralGrid * 0.35 * exp(-r * 1.8);

  // Radiant Golden Core / Lotus Stamen
  float coreDist = r;
  float coreGlow = 0.04 / (coreDist * coreDist * 6.0 + 0.04);
  float corePulse = 1.0 + 0.4 * sin(t * 4.0) + bass * 0.8;
  vec3 coreColor = mix(vec3(1.0, 0.95, 0.5), vec3(1.0, 0.4, 0.1), clamp(r * 5.0, 0.0, 1.0));
  col = col + coreColor * coreGlow * corePulse * 1.2;

  // Stardust / Pollen particles swirling around the flower
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float pAngle = fi * 1.047 + t * (0.8 + 0.2 * fi);
    float pRad = 0.25 + 0.15 * sin(fi * 2.1 + t * 1.5) + bass * 0.1;
    vec2 pPos = vec2(cos(pAngle), sin(pAngle)) * pRad;
    float pDist = length(p - pPos);
    float pGlow = 0.003 / (pDist * pDist * 25.0 + 0.003);
    col = col + vec3(1.0, 0.9, 0.4) * pGlow * (0.8 + 0.8 * spark);
  }

  // Soft tone mapping and cinematic vignette
  col = col / (col + vec3(0.85));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  // RGBA recto: el motor multiplica por alpha al componer.
  float alpha = clamp(max(col.r, max(col.g, col.b)) * 1.6, 0.0, 1.0);
  return vec4(clamp(col, 0.0, 1.0), alpha);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

// Multi-octave convective solar plasma noise
float solarNoise(vec2 p, float t) {
  float n = 0.0;
  n = n + sin(p.x * 6.0 + t * 1.2) * cos(p.y * 6.0 - t * 0.9);
  n = n + sin(p.x * 14.0 - t * 1.8 + p.y * 5.0) * 0.5;
  n = n + cos(p.y * 24.0 + t * 3.1 - p.x * 10.0) * 0.25;
  n = n + sin((p.x + p.y) * 36.0 + t * 4.5) * 0.12;
  return n * 0.53;
}

// Blackbody thermal incandescent ramp (0=dark vacuum, 1=blinding white)
vec3 blackbody(float heat) {
  vec3 col = vec3(0.0);
  col = mix(col, vec3(0.65, 0.03, 0.0), smoothstep(0.0, 0.32, heat));
  col = mix(col, vec3(1.0, 0.32, 0.02), smoothstep(0.24, 0.62, heat));
  col = mix(col, vec3(1.0, 0.88, 0.18), smoothstep(0.52, 0.82, heat));
  col = mix(col, vec3(1.0, 1.0, 0.98), smoothstep(0.78, 1.05, heat));
  return col;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float t = f.time * 0.55 * f.speed;
  float bass = clamp(f.bass, 0.0, 1.0);
  float beat = clamp(f.pulse, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);

  float r = length(p);
  float a = getAngle(p);

  // Stellar core radius with bass pulsation
  float coreRadius = 0.34 + bass * 0.09 + beat * 0.04;

  // Background deep space with hot ambient nebula dust
  vec3 col = vec3(0.015, 0.003, 0.008) + vec3(0.14, 0.018, 0.0) * exp(-r * 1.6);

  // Shockwave blast rings propagating outward
  float wavePhase = mod(r * 2.8 - t * 2.0, 2.0);
  float shock = exp(-abs(wavePhase - 1.0) * 14.0) * exp(-r * 0.9);
  col = col + vec3(1.0, 0.45, 0.08) * shock * (0.6 + 0.9 * bass);

  // Solar Prominences / coronal mass ejections (flares radiating outward)
  float flares = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float flareAngle = fi * 1.047 + sin(t * 0.4 + fi * 1.2) * 0.35;
    float da = abs(mod(a - flareAngle + 3.14159, 6.28318) - 3.14159);
    float flareDist = abs(r - (coreRadius + 0.18 + 0.16 * sin(t * 2.2 + fi * 2.0) + bass * 0.18));
    float flareIntensity = exp(-da * 8.5) * exp(-flareDist * 9.0);
    flares = flares + flareIntensity;
  }
  col = col + vec3(1.0, 0.38, 0.06) * flares * 2.0;

  // Ethereal coronal streamers (solar wind filaments)
  float rays = sin(a * 16.0 + t * 2.2 + sin(r * 6.0 - t * 3.5)) * 0.5 + 0.5;
  rays = rays * smoothstep(coreRadius * 0.8, 1.3, r) * exp(-r * 2.0);
  col = col + vec3(1.0, 0.55, 0.12) * rays * (0.8 + 0.8 * beat);

  // Magnetic coronal loops (toroidal magnetic flux arches)
  for (int m = 0; m < 5; m++) {
    float fm = float(m);
    vec2 loopCenter = vec2(cos(fm * 1.256 + t * 0.35), sin(fm * 1.256 + t * 0.35)) * (coreRadius * 0.92);
    float dLoop = length(p - loopCenter);
    float loopRadius = 0.13 + 0.05 * sin(t * 1.6 + fm * 1.8);
    float loopRing = abs(dLoop - loopRadius);
    float loopGlow = 0.0035 / (loopRing * loopRing * 22.0 + 0.004);
    col = col + vec3(1.0, 0.75, 0.25) * loopGlow * (0.7 + 0.6 * spark);
  }

  // Solar photosphere surface with boiling convective granulation
  if (r < coreRadius * 1.25) {
    vec2 surfCoord = rotate2D(p, t * 0.18);
    float granulation = solarNoise(surfCoord * 5.0, t * 1.5);

    // Radial darkening towards the limb, searing nuclear interior
    float radialFactor = clamp((coreRadius - r) / coreRadius, 0.0, 1.0);
    float heat = radialFactor * 0.92 + granulation * 0.32 + bass * 0.35;
    vec3 sunSurface = blackbody(clamp(heat, 0.0, 1.25));

    // Crisp limb transition with solar atmosphere rim
    float diskAlpha = smoothstep(coreRadius + 0.02, coreRadius - 0.02, r);
    col = mix(col, sunSurface, diskAlpha);
  }

  // Radiant nuclear core glow
  float coreGlow = 0.06 / (r * r * 8.5 + 0.06);
  col = col + vec3(1.0, 0.92, 0.75) * coreGlow * (0.9 + 1.1 * bass);

  // High-energy relativistic plasma sparks
  for (int s = 0; s < 8; s++) {
    float fs = float(s);
    float spAngle = fs * 0.785 + t * (1.3 + 0.25 * fs);
    float spRad = coreRadius + 0.10 + 0.28 * fract(sin(fs * 43.12) * 532.1 + t * 0.45);
    vec2 spPos = vec2(cos(spAngle), sin(spAngle)) * spRad;
    float spDist = length(p - spPos);
    float sparkGlow = 0.002 / (spDist * spDist * 32.0 + 0.002);
    col = col + vec3(1.0, 0.9, 0.4) * sparkGlow * (1.0 + 1.3 * spark);
  }

  // Soft tone mapping and subtle vignette
  col = col / (col + vec3(0.82));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  return vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Star { float radius, angle, lift, drift; int group; };
  std::vector<Star> stars;
  float turn = 0, breath = 0;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); stars.clear(); stars.reserve(1500); turn=0; breath=0;
    for(int i=0;i<1500;i++) {
      float r=std::sqrt(rng.unit()); int arm=i%4;
      stars.push_back({r, float(arm*pi/2)+r*5.8f+(rng.unit()-.5f)*(.25f+r*.8f),
        (rng.unit()-.5f)*(.018f+r*.035f), .7f+rng.unit()*.6f, i%9});
    }
  }
  void update(const Frame& f) override {
    turn += float(f.delta)*f.speed*.06f;
    float target=f.music.energy;
    breath += (target-breath)*float(1-std::exp(-f.delta*3));
  }
  void render(const Frame& f, Canvas& c) const override {
    Paint sky=Paint::radial({f.width*.5f,f.height*.47f},f.height*.75f,
      {Color::argb(0xff151031),Color::argb(0xff03040d)});
    c.rect({0,0,f.width,f.height},sky);
    c.save(); c.translate(f.width*.5f,f.height*.48f); c.rotate(-.38f);
    float scale=std::min(f.width*.62f,f.height*.42f)*(1+breath*.045f);
    Paint haze=Paint::radial({0,0},scale*.8f,{Color{.24f,.1f,.5f,.2f},Color{.08f,.02f,.3f,0}});
    haze.blend=Blend::plus; c.rect({-scale,-scale,scale*2,scale*2},haze);
    for(int group=0;group<9;group++) {
      std::vector<Vec2> batch;batch.reserve(170);
      for(const auto& s:stars) if(s.group==group) {
        float a=s.angle+turn*s.drift;
        batch.push_back({std::cos(a)*s.radius*scale,
          std::sin(a)*s.radius*scale*.49f+s.lift*scale});
      }
      Paint p;p.blend=Blend::plus;
      p.color=group%3==0?Color{.58f,.69f,1,.65f}:group%3==1?Color{1,.67f,.48f,.6f}:Color{.9f,.72f,1,.72f};
      c.points(batch,.55f+(group/3)*.5f,p);
    }
    Paint core=Paint::radial({0,0},scale*.28f,{Color{1,.87f,.68f,.92f},Color{.65f,.34f,.75f,.22f},Color{.2f,.1f,.6f,0}},{0,.22f,1});
    core.blend=Blend::screen;c.circle({0,0},scale*.28f,core);c.restore();
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, seeds{}, power{};
  float phase = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 3 ? 0.55f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.3f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      if (strike) base[i] += (rng.unit() - 0.5f) * 2.2f;
      base[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
    }
    phase += dt * f.speed * (0.6f + 1.6f * drive + 1.2f * kick);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, f.detail});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma_globe", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma_globe:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

const float R = 0.34;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Devuelve (núcleo, halo) de un filamento que va del centro al cristal.
vec2 filament(vec2 p, float ang, float power, float seed) {
  if (power < 0.02) return vec2(0.0);
  float t = uA.x;
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);
  float along = dot(p, dir);
  float s = clamp(along / R, 0.0, 1.0);
  float env = sin(3.14159 * s) * (0.6 + 0.4 * s);
  float disp = (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.07 +
                sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.03) * env * R;
  disp += (noise(vec2(s * 38.0 + seed, t * 9.0)) - 0.5) * (0.02 + 0.07 * uM.x) * env * R;
  float lateral = dot(p, nrm) - disp;
  float inside = smoothstep(-0.01, 0.02, along) * smoothstep(R * 1.01, R * 0.96, along);
  float width = (0.0030 + 0.0040 * min(power, 1.5)) * (1.0 - 0.45 * s);
  float core = exp(-lateral * lateral / (width * width));
  float halo = (0.00006 + 0.00012 * power) / (lateral * lateral + 0.00025);
  // Punto de contacto con el cristal.
  vec2 tip = dir * R + nrm * disp;
  float contact = exp(-dot(p - tip, p - tip) / (0.00025 + 0.0004 * power));
  return vec2((core * 1.4 + contact * 1.6) * inside * power + contact * power * 0.6,
              halo * inside * power);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  p.y -= 0.04;
  float r = length(p);
  float kick = uA.z;

  // Sala oscura con resplandor de color detrás del globo.
  vec3 col = uC0 + mix(uC2, uC1, 0.4) * exp(-r * r * 4.0) * (0.10 + 0.30 * kick + 0.12 * uA.w);

  // Peana bajo el globo.
  float baseTop = -R * 0.93;
  float baseW = 0.11 + (baseTop - p.y) * 0.35;
  float pedestal = step(p.y, baseTop) * step(abs(p.x), baseW) * step(baseTop - 0.22, p.y);
  float sheen = smoothstep(baseW, baseW * 0.2, abs(p.x - baseW * 0.35));
  vec3 pedestalCol = uC0 * 0.5 + vec3(0.05) * sheen +
                     mix(uC1, uC2, 0.5) * 0.18 * exp(-(baseTop - p.y) * 40.0) * (0.4 + kick);
  col = mix(col, pedestalCol, pedestal);

  if (r < R * 1.02) {
    // Gas interior y electrodo central.
    float inside = smoothstep(R, R * 0.97, r);
    vec3 gas = mix(uC2, uC1, 0.5 + 0.5 * sin(atan(p.y, p.x) * 2.0 + uA.x * 0.3)) *
               (0.015 + 0.04 * uA.w + 0.10 * kick) * (0.6 + 0.4 * noise(p * 6.0 + uA.x * 0.2));
    col = mix(col, uC0 * 0.35 + gas, inside);

    vec2 acc = vec2(0.0);
    acc += filament(p, uAng0.x, uPow0.x, 0.0);
    acc += filament(p, uAng0.y, uPow0.y, 1.7);
    acc += filament(p, uAng0.z, uPow0.z, 3.1);
    acc += filament(p, uAng0.w, uPow0.w, 4.6);
    acc += filament(p, uAng1.x, uPow1.x, 6.2);
    acc += filament(p, uAng1.y, uPow1.y, 7.9);
    acc += filament(p, uAng1.z, uPow1.z, 9.3);
    acc += filament(p, uAng1.w, uPow1.w, 10.8);
    vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.6, 0.0, 1.0)) * acc.x;
    arc += uC1 * acc.y;
    col += arc * inside * (0.9 + 0.8 * uA.y) * uM.z;

    float coreR = 0.05 + 0.006 * uA.y + 0.01 * kick;
    float electrode = smoothstep(coreR, coreR * 0.85, r);
    vec3 electrodeCol = mix(uC1, uC3, 0.6) * (1.2 + 1.5 * kick) * (0.75 + 0.25 * smoothstep(coreR, 0.0, length(p - vec2(-0.015, 0.015))));
    col = mix(col, electrodeCol, electrode);
    col += uC1 * (0.0005 + 0.0025 * kick) / (r * r + 0.0025) * inside;

    // Cristal: borde con Fresnel y reflejo de ventana.
    float rim = gauss((r - R) / 0.006);
    col += mix(uC2, vec3(1.0), 0.5) * rim * (0.35 + 0.4 * kick);
    col += uC2 * smoothstep(R * 0.8, R, r) * inside * 0.06;
    vec2 hl = p - vec2(-0.13, 0.17);
    float highlight = exp(-dot(hl * vec2(1.0, 1.8), hl * vec2(1.0, 1.8)) * 140.0);
    col += vec3(1.0) * highlight * 0.12;
    float arcHl = gauss((r - R * 0.9) / 0.01) * smoothstep(0.2, 0.9, dot(normalize(p + vec2(1e-5, 0.0)), normalize(vec2(-0.6, 0.8))));
    col += vec3(1.0) * arcHl * 0.15;
  }

  col += uC3 * uM.y * 0.15;
  col *= 1.0 - 0.4 * smoothstep(0.45, 1.2, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

