#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, altura del fuego, golpe, energía
uniform vec4 uB;   // chispas del golpe: fuerza, edad, x; agudos
uniform vec4 uX;   // medios, destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s;
}

float fbmLow(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875 * 0.97;
}

// Rampa de cuerpo negro teñida con la paleta: rojo profundo, naranja, oro, blanco.
vec3 fireColor(float x) {
  vec3 c = mix(uC0, uC1, smoothstep(0.0, 0.25, x));
  c = mix(c, uC2, smoothstep(0.2, 0.55, x));
  c = mix(c, uC3, smoothstep(0.5, 0.85, x));
  c = mix(c, vec3(1.0, 0.98, 0.92), smoothstep(0.9, 1.15, x));
  return c * (0.3 + 1.2 * x);
}

float embers(vec2 p, float t, float cells, float speed, float seed, float density) {
  vec2 g = vec2(p.x * cells, (p.y - t * speed) * cells);
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  float h = hash12(id + seed);
  vec2 o = vec2(hash12(id + seed + 1.7), hash12(id + seed + 4.2)) - 0.5;
  o.x += 0.3 * sin(t * 2.0 + h * 30.0);
  float d = length((f - o * 0.6) * vec2(1.0, 0.3));
  return smoothstep(0.07, 0.0, d) * step(1.0 - density, h) * (0.6 + 0.4 * sin(t * 30.0 + h * 80.0));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;
  float bottom = -0.5 * uSize.y / scale;
  float h = uv.y - bottom;                 // altura sobre el borde inferior
  float height = 0.25 + 1.05 * uA.y;       // altura de las llamas

  // Calima: el aire caliente ondula por encima del fuego.
  vec2 p = uv;
  if (h < height * 2.0 + 0.2) {
    p.x += (noise(vec2(uv.x * 6.0, h * 4.0 - t * 2.0)) - 0.5) * 0.03 * smoothstep(0.1, 0.8, h);
  }

  vec3 col = uC0;
  // Resplandor cálido sólo alrededor del fuego.
  float glowR = length(vec2(p.x * 0.8, h - height * 0.35));
  col += uC1 * 0.06 * exp(-glowR * glowR * 3.0 / max(height, 0.15)) * (0.6 + 0.8 * uA.y);

  // Las llamas sólo existen en la parte baja: por encima la GPU se salta el ruido.
  if (h < height * 1.2 + 0.05) {
    // Ruido estirado en vertical: lenguas de fuego que suben y se rompen.
    vec2 q = vec2(p.x * 3.4, h * 1.5 - t * 1.9);
    vec2 warp = vec2(fbmLow(q * 0.6 + vec2(0.0, -t * 0.5)), fbmLow(q * 0.6 + vec2(3.7, -t * 0.6)));
    float n = fbm(q + (warp - 0.5) * 1.8);
    float licks = noise(vec2(p.x * 9.0, h * 3.0 - t * 4.0));
    float tongues = 0.7 + 0.3 * sin(p.x * 6.5 + noise(vec2(p.x * 2.5, t * 0.5)) * 5.0);
    float shape = 1.0 - h / (height * tongues);
    float widthMask = smoothstep(1.05, 0.2, abs(p.x) * (1.3 - 0.35 * uA.y));
    float flame = shape * widthMask * 1.55 - n * 1.05 - licks * 0.18 + 0.2;
    float body = smoothstep(0.0, 0.06, flame);
    float heat = clamp(flame * 0.85, 0.0, 1.0) * (0.66 + 0.22 * uA.z + 0.08 * uX.x);
    col += fireColor(heat) * body;
  }
  // Lecho de brasas en la base.
  if (h < 0.3) {
    float bed = exp(-h * 22.0) * (0.55 + 0.45 * noise(vec2(p.x * 14.0, t * 0.6)));
    col += fireColor(0.5 + 0.25 * noise(vec2(p.x * 9.0, t))) * bed * (0.7 + 0.5 * uA.y);
  }

  // Humo tenue en una franja por encima de las llamas.
  float smokeBand = smoothstep(height * 0.8, height * 1.5, h) * smoothstep(height * 2.6 + 0.5, height * 1.6, h);
  if (smokeBand > 0.0) {
    float smoke = fbmLow(vec2(p.x * 2.0, h * 1.5 - t * 0.35) + 9.0);
    col = mix(col, uC0 * 1.8, smoothstep(0.55, 0.85, smoke) * smokeBand * 0.4);
  }

  // Brasas: pocas, cerca del fuego y como estelas; más con los agudos.
  float density = 0.02 + 0.06 * uB.w + 0.03 * uA.w;
  float e = embers(p, t * 0.3, 14.0, 1.1, 0.0, density) +
            embers(p, t * 0.3, 24.0, 1.6, 13.0, density * 0.7) * 0.7;
  float fade = smoothstep(height * 1.6, height * 0.2, h) * smoothstep(1.0, 0.3, abs(p.x));
  col += mix(uC2, uC3, 0.5) * e * fade * 1.6;
  float age = uB.y;
  if (age < 2.5 && uB.x > 0.01) {
    vec2 bp = p - vec2(uB.z, bottom + height * 0.4 + age * 1.1);
    float spray = embers(bp * vec2(1.0, 0.7), 0.0, 22.0, 0.0, 31.0, 0.4);
    float cloud = exp(-dot(bp, bp) * 5.0 / (0.15 + age));
    col += mix(uC2, uC3, 0.7) * spray * cloud * uB.x * exp(-age * 1.6) * 3.0;
  }

  col += uC3 * uX.y * 0.15;
  col *= uX.z;
  col *= 1.0 - 0.35 * smoothstep(0.5, 1.3, length(uv * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  std::vector<Vec2> buckets[6];
  float waveTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float step = 12.0f, cols = 0, rows = 0, lastW = 0, lastH = 0, lastDetail = -1.0f;
  void build(float w, float h, float detail) {
    step = std::max(9.0f, std::min(w, h) / (18.0f + 16.0f * detail));
    cols = std::ceil(w / step) + 1.0f;
    rows = std::ceil(h / step) + 1.0f;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    for (int i = 0; i < 6; i++) buckets[i].clear();
    waveTime = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    lastW = 0; lastH = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en una ondulación zen (~0.10f).
    // Con música acelera la onda y multiplica la amplitud vertical.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    waveTime += dt * f.speed * audioDrive;

    float w = f.width, h = f.height;
    float t = waveTime;
    if (w != lastW || h != lastH || f.detail != lastDetail) {
      build(w, h, f.detail);
      lastW = w; lastH = h; lastDetail = f.detail;
    }
    float amp = 1.0f + smoothBass * 0.85f;
    float s1x = w * (0.5f + std::sin(t * 0.35f) * 0.32f);
    float s1y = h * (0.35f + std::sin(t * 0.27f + 1.0f) * 0.2f);
    float s2x = w * (0.5f + std::sin(t * 0.31f + 2.4f) * 0.34f);
    float s2y = h * (0.68f + std::sin(t * 0.23f + 3.0f) * 0.2f);
    for (int i = 0; i < 6; i++) buckets[i].clear();
    for (int j = 0; j < int(rows); j++) {
      float y = float(j) * step;
      for (int i = 0; i < int(cols); i++) {
        float x = float(i) * step;
        float dx1 = x - s1x, dy1 = y - s1y;
        float dx2 = x - s2x, dy2 = y - s2y;
        float d1 = std::sqrt(dx1 * dx1 + dy1 * dy1);
        float d2 = std::sqrt(dx2 * dx2 + dy2 * dy2);
        float v = std::sin(d1 * 0.085f - t * 2.4f) + std::sin(d2 * 0.07f - t * 1.9f);
        float k = (v + 2.0f) * 0.25f;
        int b = int(k * 5.99f);
        if (b < 0) b = 0; if (b > 5) b = 5;
        buckets[b].push_back({x, y + (k - 0.5f) * step * 0.55f * amp});
      }
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    Paint bg; bg.color = Color::argb(0xff03071c);
    c.rect({0, 0, w, h}, bg);
    const uint32_t pal[6] = {0xff0a1b4a, 0xff123a8a, 0xff1f6fd0,
      0xff35b3f0, 0xff7fe9ff, 0xffd9fbff};
    for (int b = 0; b < 6; b++) {
      if (buckets[b].empty()) continue;
      Color cc = Color::argb(pal[b]);
      Paint p; p.blend = Blend::plus;
      p.color = {cc.r, cc.g, cc.b, std::min(1.0f, (0.55f + 0.45f * f.music.energy) * f.intensity)};
      c.points(buckets[b], (1.0f + float(b) / 5.0f * step * 0.42f) * 0.5f, p);
    }
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, mids = 0;
  float travel = 0, travelVel = 0, rotOuter = 0, rotInner = 0, embers = 0;
  float voidPush = 0, voidVel = 0, burst = 0, ringR = 3.0f, ringAmp = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = mids = 0;
    travel = rng.unit() * 10.0f;
    travelVel = 0;
    rotOuter = rng.unit() * 6.2831853f;
    rotInner = rng.unit() * 6.2831853f;
    embers = rng.unit() * 10.0f;
    voidPush = voidVel = burst = 0;
    ringR = 3.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float mi = 0;
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    mids = follow(mids, mi, 12.0f, 3.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      voidVel += 1.4f * hit;
      travelVel += 0.9f * hit;
      burst = std::max(burst, hit);
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    // El anillo negro se expande con el golpe y vuelve con un muelle amortiguado.
    voidVel += (-voidPush * 30.0f - voidVel * 6.0f) * dt;
    voidPush += voidVel * dt;
    travelVel *= std::exp(-dt * 3.0f);
    travel += dt * f.speed * (0.10f + 0.55f * drive) + dt * travelVel;
    rotOuter += dt * f.speed * (0.03f + 0.18f * mids + 0.05f * drive);
    rotInner -= dt * f.speed * (0.05f + 0.30f * mids + 0.08f * drive);
    embers += dt * f.speed * (0.25f + 0.9f * drive + 0.8f * burst);
    burst *= std::exp(-dt * 2.5f);
    ringR += dt * (0.7f + 0.4f * drive);
    ringAmp *= std::exp(-dt * 2.4f);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float vin = 0.16f + 0.015f * bass * amp;
    float vout = 0.30f + 0.10f * voidPush * amp;
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {travel, bass * amp, kick * amp, energy});
    u.insert(u.end(), {rotOuter, rotInner, spark * amp, f.glow});
    u.insert(u.end(), {vin, std::max(vout, vin + 0.06f), kick * amp, flash});
    u.insert(u.end(), {embers, burst * amp, ringR, ringAmp * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("fire_mandala", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.fire_mandala:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // viaje, graves, golpe, energía
uniform vec4 uB;   // giro exterior, giro interior, agudos, glow
uniform vec4 uV;   // radio interior y exterior del anillo negro, fogonazo, destello
uniform vec4 uE;   // reloj de brasas, ráfaga, radio y fuerza del anillo del golpe
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Distancia al contorno de un polígono regular de n lados (apotema ap).
float polygon(float r, float a, float n, float ap, float rot) {
  float sector = TAU / n;
  float th = mod(a + rot + 0.5 * sector, sector) - 0.5 * sector;
  return abs(r * cos(th) - ap);
}

// Distancia en arco al rayo radial más cercano de m rayos.
float rays(float r, float a, float m, float rot) {
  float s = fract((a + rot) * m / TAU) - 0.5;
  return abs(s) * (TAU / m) * r;
}

// Línea de neón con halo ceñido: el negro entre líneas queda limpio.
// Rampa de fuego: halos de brasa roja, líneas naranjas, oro y blanco sólo
// donde la luz es más intensa.
vec3 fireRamp(float I) {
  vec3 c = mix(uC1, uC2, smoothstep(0.05, 0.7, I));
  c = mix(c, uC3, smoothstep(1.6, 3.0, I));
  c = mix(c, vec3(1.0, 0.95, 0.85), smoothstep(3.0, 4.2, I));
  return c * min(I, 2.2) * 0.62;
}

float lineGlow(float d, float w) {
  float g = w * w / (d * d + w * w);
  return g * g;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = max(length(p), 0.0005);
  float a = atan(p.y, p.x);
  float kick = uA.z;
  float bass = uA.y;
  float vin = uV.x;
  float vout = uV.y;
  float width = 0.0032 + 0.002 * bass;

  float energyLines = 0.0;

  // Exterior: rayos finos que titilan como fuego y estrellas que viajan hacia fuera.
  if (r > vout * 0.9) {
    float flick = 0.65 + 0.35 * hash12(vec2(floor((a + uB.x) * 64.0 / TAU), floor(uA.x * 8.0)));
    float ray = lineGlow(rays(r, a, 64.0, uB.x), width * 0.8) * smoothstep(vout, vout + 0.1, r);
    ray *= (0.45 + 0.35 * flick + 0.6 * uB.z * flick) * exp(-(r - vout) * 0.6);
    float bigRays = lineGlow(rays(r, a, 16.0, -uB.x * 0.5), width * 1.4) * smoothstep(vout, vout + 0.05, r);
    energyLines += ray + bigRays * 0.8;
    for (int k = 0; k < 3; k++) {
      float fk = float(k);
      float ph = fract(uA.x * 0.35 + fk / 3.0);
      float ap = vout + 0.02 + ph * 1.1;
      float fade = sin(3.14159 * ph);
      float rot = (mod(fk, 2.0) < 1.0 ? uB.x : -uB.x) * 1.5;
      float d = min(polygon(r, a, 8.0, ap, rot), polygon(r, a, 8.0, ap, rot + TAU / 16.0));
      energyLines += lineGlow(d, width * 1.5) * fade * 1.4;
    }
  }

  // Centro: rosetón de polígonos superpuestos que gira al revés.
  if (r < vin * 1.1) {
    float rot = uB.y;
    float d = min(polygon(r, a, 12.0, vin * 0.82, rot), polygon(r, a, 12.0, vin * 0.82, rot + TAU / 24.0));
    d = min(d, polygon(r, a, 8.0, vin * 0.58, -rot * 1.4));
    d = min(d, polygon(r, a, 8.0, vin * 0.58, -rot * 1.4 + TAU / 16.0));
    d = min(d, abs(r - vin * 0.28));
    d = min(d, abs(r - vin * 0.95));
    d = min(d, rays(r, a, 24.0, rot * 0.7) + max(0.0, vin * 0.3 - r));
    float bloom = 1.0 + 0.8 * kick + 0.5 * bass;
    energyLines += lineGlow(d, width * 0.9) * smoothstep(vin * 1.02, vin * 0.9, r) * bloom;
  }

  // Bordes del anillo negro: brillan y estallan con el golpe.
  float rimOut = exp(-(r - vout) * (r - vout) * 7000.0);
  float rimIn = exp(-(r - vin) * (r - vin) * 9000.0);
  energyLines += (rimOut * (0.5 + 2.2 * uV.z) + rimIn * (0.4 + 1.2 * uV.z));

  // Anillo de choque que sale del anillo negro con cada golpe.
  float ringR = vout + uE.z;
  energyLines += uE.w * exp(-(r - ringR) * (r - ringR) * 900.0) * 1.3;

  // Rampa de fuego: brasa, naranja, oro y blanco incandescente.
  float I = energyLines * uB.w * (0.8 + 0.4 * uA.w);
  vec3 col = uC0 + fireRamp(I);

  // Brasas que suben por los rayos hacia fuera.
  if (r > vout) {
    float lanesA = (a + uB.x) * 64.0 / TAU;
    float lane = log(r) * 16.0 - uE.x * 3.0;
    vec2 cell = vec2(floor(lanesA), floor(lane));
    float h = hash12(cell);
    float density = 0.04 + 0.16 * uB.z + 0.3 * uE.y;
    if (h > 1.0 - density) {
      float fy = fract(lane) - 0.5;
      float fx = fract(lanesA) - 0.5;
      float e = exp(-(fx * fx * 160.0 + fy * fy * 40.0)) * (0.6 + 0.4 * hash12(cell + 7.0));
      col += mix(uC2, uC3, 0.5) * e * (0.7 + 1.4 * uE.y + 0.6 * uB.z);
    }
  }

  // Núcleo incandescente y destello del flash.
  col += uC2 * (0.0005 + 0.003 * kick + 0.001 * bass) / (r * r + 0.0012);
  col += uC1 * uV.w * 0.06;

  col *= 1.0 - 0.35 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  // Mapeo de tonos que conserva el tono: comprime el brillo sin desplazar el
  // naranja hacia amarillo cuando una línea es muy intensa.
  float peak = max(col.r, max(col.g, col.b));
  float mapped = clamp((peak * (2.51 * peak + 0.03)) / (peak * (2.43 * peak + 0.59) + 0.14), 0.0, 1.0);
  col *= mapped / max(peak, 0.0001);
  col = pow(max(col, 0.0), vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

