float liquidField(vec2 p, float t, float bass, float spark, float flow) {
  float r = length(p);
  // Concentric liquid ripples expanding from center
  float ripple = sin(r * (14.0 + 3.0 * flow) - t * 3.8) * (0.035 + 0.055 * bass);

  // Cross-interfering droplet orbits
  vec2 c1 = vec2(sin(t * 0.7) * 0.42, cos(t * 0.8) * 0.35);
  vec2 c2 = vec2(cos(t * 0.9 + 1.8) * 0.38, sin(t * 0.6) * 0.42);
  float wave1 = sin(length(p - c1) * 16.0 - t * 4.2) * (0.025 + 0.035 * bass);
  float wave2 = sin(length(p - c2) * 18.0 - t * 3.6) * (0.020 + 0.030 * spark);

  // High-frequency surface sizzle from spark / hi-hats
  float sizzle = sin(p.x * 32.0 + t * 4.5) * cos(p.y * 32.0 + t * 4.0) * (0.006 + 0.018 * spark);

  // Base organic dome
  float dome = exp(-r * r * 2.2) * 0.16;

  return dome + ripple + wave1 + wave2 + sizzle;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.1;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.48;

  // Surface Normal via finite differences
  float eps = 0.0035;
  float hC = liquidField(p, t, bass, spark, flow);
  float hR = liquidField(p + vec2(eps, 0.0), t, bass, spark, flow);
  float hU = liquidField(p + vec2(0.0, eps), t, bass, spark, flow);

  vec3 normal = normalize(vec3((hC - hR) / eps, (hC - hU) / eps, 0.32));

  // Environmental reflection vector
  vec3 view = normalize(vec3(p * 0.22, 1.0));
  vec3 ref = reflect(-view, normal);

  // Studio lighting environment ramp (chrome horizon, deep velvet zenith)
  float horizon = smoothstep(-0.25, 0.25, ref.y);
  float stripe = sin(ref.y * 12.0 + ref.x * 6.0 + t * 0.25);
  float studioStripe = smoothstep(0.35, 0.75, stripe);

  vec3 deepMetal = vec3(0.02, 0.035, 0.07);
  vec3 silver = vec3(0.85, 0.90, 0.98);
  vec3 neonCyan = vec3(0.20, 0.85, 1.0);
  vec3 neonMagenta = vec3(0.95, 0.20, 0.65);

  vec3 chrome = mix(deepMetal, silver, horizon * 0.8 + studioStripe * 0.25);

  // Directional specular glints
  vec3 lightDir1 = normalize(vec3(-0.45, 0.7, 0.6));
  float spec1 = pow(max(dot(ref, lightDir1), 0.0), 36.0) * (1.6 + 2.4 * spark);
  vec3 lightDir2 = normalize(vec3(0.55, -0.5, 0.55));
  float spec2 = pow(max(dot(ref, lightDir2), 0.0), 22.0) * (0.8 + 1.4 * bass);

  // Fresnel rim glow with subtle chromatic sheen
  float fresnel = pow(1.0 - max(dot(normal, view), 0.0), 2.6);
  vec3 rimColor = mix(neonCyan, neonMagenta, 0.5 + 0.5 * sin(t * 0.35 + p.y * 2.2));

  // Combine chrome surface
  vec3 surface = chrome + (spec1 + spec2) * vec3(1.0, 0.98, 0.93) + fresnel * rimColor * (0.65 + 0.85 * energy);

  // Smooth dropoff into deep velvet background
  float fluidAlpha = smoothstep(1.4, 0.85, length(p));
  vec3 bg = vec3(0.015, 0.02, 0.035) * (1.0 - 0.45 * length(p));
  vec3 finalColor = mix(bg, surface, fluidAlpha);

  return vec4(clamp(finalColor * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

float liquidField(vec2 p, float t, float bass, float spark, float flow) {
  float r = length(p);
  // Concentric liquid ripples expanding from center
  float ripple = sin(r * (14.0 + 3.0 * flow) - t * 3.8) * (0.035 + 0.055 * bass);

  // Cross-interfering droplet orbits
  vec2 c1 = vec2(sin(t * 0.7) * 0.42, cos(t * 0.8) * 0.35);
  vec2 c2 = vec2(cos(t * 0.9 + 1.8) * 0.38, sin(t * 0.6) * 0.42);
  float wave1 = sin(length(p - c1) * 16.0 - t * 4.2) * (0.025 + 0.035 * bass);
  float wave2 = sin(length(p - c2) * 18.0 - t * 3.6) * (0.020 + 0.030 * spark);

  // High-frequency surface sizzle from spark / hi-hats
  float sizzle = sin(p.x * 32.0 + t * 4.5) * cos(p.y * 32.0 + t * 4.0) * (0.006 + 0.018 * spark);

  // Base organic dome
  float dome = exp(-r * r * 2.2) * 0.16;

  return dome + ripple + wave1 + wave2 + sizzle;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.1;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.48;

  // Surface Normal via finite differences
  float eps = 0.0035;
  float hC = liquidField(p, t, bass, spark, flow);
  float hR = liquidField(p + vec2(eps, 0.0), t, bass, spark, flow);
  float hU = liquidField(p + vec2(0.0, eps), t, bass, spark, flow);

  vec3 normal = normalize(vec3((hC - hR) / eps, (hC - hU) / eps, 0.32));

  // Environmental reflection vector
  vec3 view = normalize(vec3(p * 0.22, 1.0));
  vec3 ref = reflect(-view, normal);

  // Studio lighting environment ramp (chrome horizon, deep velvet zenith)
  float horizon = smoothstep(-0.25, 0.25, ref.y);
  float stripe = sin(ref.y * 12.0 + ref.x * 6.0 + t * 0.25);
  float studioStripe = smoothstep(0.35, 0.75, stripe);

  vec3 deepMetal = vec3(0.02, 0.035, 0.07);
  vec3 silver = vec3(0.85, 0.90, 0.98);
  vec3 neonCyan = vec3(0.20, 0.85, 1.0);
  vec3 neonMagenta = vec3(0.95, 0.20, 0.65);

  vec3 chrome = mix(deepMetal, silver, horizon * 0.8 + studioStripe * 0.25);

  // Directional specular glints
  vec3 lightDir1 = normalize(vec3(-0.45, 0.7, 0.6));
  float spec1 = pow(max(dot(ref, lightDir1), 0.0), 36.0) * (1.6 + 2.4 * spark);
  vec3 lightDir2 = normalize(vec3(0.55, -0.5, 0.55));
  float spec2 = pow(max(dot(ref, lightDir2), 0.0), 22.0) * (0.8 + 1.4 * bass);

  // Fresnel rim glow with subtle chromatic sheen
  float fresnel = pow(1.0 - max(dot(normal, view), 0.0), 2.6);
  vec3 rimColor = mix(neonCyan, neonMagenta, 0.5 + 0.5 * sin(t * 0.35 + p.y * 2.2));

  // Combine chrome surface
  vec3 surface = chrome + (spec1 + spec2) * vec3(1.0, 0.98, 0.93) + fresnel * rimColor * (0.65 + 0.85 * energy);

  // Smooth dropoff into transparency
  float fluidAlpha = smoothstep(1.35, 0.65, length(p));
  float alpha = fluidAlpha * smoothstep(0.04, 0.20, max(surface.r, max(surface.g, surface.b)));

  // RGBA recto: el motor multiplica por alpha al componer.
  return vec4(clamp(surface * f.intensity * f.glow, 0.0, 1.0), alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Blob { float radius, p1, p2, sx, sy; };
  std::vector<Blob> blobs;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float phase = 0, hue = 0, swell = 0;
  std::array<float, 12> rings{};  // x, y, radio, amplitud por onda
  int nextRing = 0;
  Random rng{9};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    blobs.clear();
    for (int i = 0; i < 6; i++)
      blobs.push_back({0.16f + rng.unit() * 0.10f, rng.unit() * 6.2831853f, rng.unit() * 6.2831853f,
                       0.21f + float(i) * 0.043f, 0.17f + float(i) * 0.037f});
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 20.0f;
    hue = rng.unit();
    swell = 0;
    rings.fill(0);
    for (int i = 0; i < 3; i++) rings[i * 4 + 2] = 3.0f;
    nextRing = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      // Nueva onda de choque desde un punto cercano al centro.
      float aspect = f.height / std::min(f.width, f.height);
      rings[nextRing * 4] = (rng.unit() - 0.5f) * 0.6f;
      rings[nextRing * 4 + 1] = (rng.unit() - 0.5f) * 0.6f * aspect;
      rings[nextRing * 4 + 2] = 0.0f;
      rings[nextRing * 4 + 3] = hit;
      nextRing = (nextRing + 1) % 3;
      hue += 0.12f * hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 3; i++) {
      rings[i * 4 + 2] += dt * (0.75f + 0.35f * drive);
      rings[i * 4 + 3] *= std::exp(-dt * 1.6f);
    }

    phase += dt * f.speed * (0.22f + 1.1f * drive + 0.9f * kick);
    hue += dt * (0.015f + 0.10f * energy + 0.06f * body);
    swell = follow(swell, bass * 0.7f + kick * 0.5f, 14.0f, 3.0f, dt);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    float hw = 0.5f * f.width / s, hh = 0.5f * f.height / s;
    float grow = 1.0f + 0.45f * swell * amp;
    std::array<float, 18> b{};
    for (int i = 0; i < 6; i++) {
      const Blob& k = blobs[i];
      b[i * 3] = hw * 0.9f * std::sin(phase * k.sx + k.p1);
      b[i * 3 + 1] = hh * 0.85f * std::sin(phase * k.sy + k.p2);
      b[i * 3 + 2] = k.radius * grow;
    }
    std::vector<float> u;
    u.reserve(56);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {hue, spark * amp, flash, f.glow});
    u.insert(u.end(), {b[0], b[1], b[3], b[4]});
    u.insert(u.end(), {b[6], b[7], b[9], b[10]});
    u.insert(u.end(), {b[12], b[13], b[15], b[16]});
    u.insert(u.end(), {b[2], b[5], b[8], b[11]});
    u.insert(u.end(), {b[14], b[17], 0.6f + 0.4f * f.detail, 0.35f + 0.9f * bass * amp});
    for (int i = 0; i < 3; i++)
      u.insert(u.end(), {rings[i * 4], rings[i * 4 + 1], rings[i * 4 + 2], rings[i * 4 + 3] * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("metal", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.metal:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;    // tiempo, graves, golpe, energía
uniform vec4 uB;    // tono, agudos, destello, glow
uniform vec4 uP0;   // centros de las gotas 0 y 1
uniform vec4 uP1;   // centros 2 y 3
uniform vec4 uP2;   // centros 4 y 5
uniform vec4 uR0;   // radios 0..3
uniform vec4 uR1;   // radios 4, 5; detalle; amplitud del oleaje
uniform vec4 uS0;   // ondas de choque: x, y, radio, amplitud
uniform vec4 uS1;
uniform vec4 uS2;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float blob(vec2 p, vec2 c, float r) {
  vec2 d = p - c;
  return exp(-dot(d, d) / (r * r));
}

float shock(vec2 p, vec4 s) {
  float d = length(p - s.xy) - s.z;
  return s.w * 0.05 * sin(d * 42.0) * exp(-d * d * 55.0);
}

float height(vec2 p) {
  float t = uA.x;
  float b = blob(p, uP0.xy, uR0.x) + blob(p, uP0.zw, uR0.y) + blob(p, uP1.xy, uR0.z) +
            blob(p, uP1.zw, uR0.w) + blob(p, uP2.xy, uR1.x) + blob(p, uP2.zw, uR1.y);
  // Metal líquido: los abultamientos se funden en una sola superficie.
  float h = b / (1.0 + 0.6 * b) * 0.2;
  vec2 q = p + 0.08 * vec2(sin(p.y * 3.1 + t * 0.7), sin(p.x * 2.7 - t * 0.6));
  h += 0.006 * uR1.w * (sin(q.x * 9.0 * uR1.z + t * 1.6) + sin(q.y * 11.0 * uR1.z - t * 1.3) +
                        sin((q.x + q.y) * 7.0 + t));
  h += shock(p, uS0) + shock(p, uS1) + shock(p, uS2);
  return h;
}

// Ciclo de color vivo a través de la paleta: c1 -> c2 -> c3 -> c1.
vec3 cycle(float x) {
  float f = fract(x) * 3.0;
  vec3 a = f < 1.0 ? uC1 : (f < 2.0 ? uC2 : uC3);
  vec3 b = f < 1.0 ? uC2 : (f < 2.0 ? uC3 : uC1);
  return mix(a, b, smoothstep(0.0, 1.0, fract(f)));
}

// Entorno de estudio que refleja el metal: cielo tornasol según la dirección,
// una franja de luz nítida que dibuja contornos y suelo oscuro para el contraste.
vec3 environment(vec3 r, float hue, float kick, float lift) {
  float tilt = length(r.xy);
  vec3 sky = cycle(hue + r.x * 0.6 + r.y * 0.35);
  vec3 col = uC0 * 0.6;
  col += sky * (0.22 * lift + 0.9 * smoothstep(0.08, 0.8, tilt)) * (1.0 + 0.5 * kick);
  float sy = r.y - 0.42;
  float sx = r.x + 0.55;
  float strip = exp(-sy * sy * 160.0) * smoothstep(0.2, 0.5, tilt);
  float strip2 = exp(-sx * sx * 220.0) * smoothstep(0.3, 0.6, tilt);
  col += mix(vec3(1.0), sky, 0.35) * (strip * 1.1 + strip2 * 0.6) * (1.0 + kick);
  col *= 0.30 + 0.70 * smoothstep(-0.5, -0.1, r.y);
  return col;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float t = uA.x;
  float kick = uA.z;

  float e = 1.5 / scale;
  float h0 = height(p);
  float hx = height(p + vec2(e, 0.0));
  float hy = height(p + vec2(0.0, e));
  vec3 n = normalize(vec3(-(hx - h0) / e, -(hy - h0) / e, 1.0));
  vec3 v = vec3(0.0, 0.0, 1.0);
  vec3 r = reflect(-v, n);

  float slope = clamp(1.0 - n.z, 0.0, 1.0);
  float fres = 0.25 + 0.75 * pow(slope, 0.8);
  float hue = uB.x + h0 * 1.2;
  vec3 iri = cycle(hue);
  // Sólo la cima de las cúpulas refleja algo de color; el fondo plano queda negro.
  float lift = smoothstep(0.03, 0.12, h0);
  vec3 col = environment(r, hue, kick, lift) * fres * (0.9 + 0.3 * uA.w) * uB.w;
  // Brillo especular nítido de la luz principal, más intenso con los agudos.
  vec3 l1 = normalize(vec3(-0.5, 0.6, 0.65));
  float s1 = pow(max(dot(n, normalize(l1 + v)), 0.0), 140.0);
  col += vec3(1.0) * s1 * (0.8 + 2.5 * uB.y);
  // Destello del golpe y del flash.
  col += iri * kick * 0.12 + vec3(1.0) * uB.z * 0.10;

  col *= 1.0 - 0.35 * smoothstep(0.5, 1.3, length(p * vec2(0.9, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, warm = 0, cool = 0;
  float phase = 0, drift = 0, push = 0;
  std::array<float, 4> shocks{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = warm = cool = 0;
    phase = rng.unit() * 30.0f;
    drift = rng.unit() * 20.0f;
    push = 0;
    shocks = {6.0f, 0.0f, 6.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float low = 0, high = 0;
    for (int i = 0; i < 10; i++) low = std::max(low, m.smoothSpectrum[i]);
    for (int i = 18; i < 31; i++) high = std::max(high, m.smoothSpectrum[i]);
    warm = follow(warm, low, 10.0f, 2.5f, dt);
    cool = follow(cool, high, 10.0f, 2.5f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      shocks[2] = shocks[0];
      shocks[3] = shocks[1];
      shocks[0] = 0.0f;
      shocks[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 4.5f), hit);
    flash = std::max(flash * std::exp(-dt * 7.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      shocks[i] += dt * 0.85f;
      shocks[i + 1] *= std::exp(-dt * 1.3f);
    }

    phase += dt * f.speed * (0.10f + 0.6f * drive + 0.5f * kick);
    drift += dt * f.speed * (0.02f + 0.08f * drive);
    push = follow(push, kick, 12.0f, 2.5f, dt);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {shocks[0], shocks[1] * amp, shocks[2], shocks[3] * amp});
    u.insert(u.end(), {warm, cool, spark * amp, f.glow});
    u.insert(u.end(), {drift, push * amp, flash, f.detail});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("nebula", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.nebula:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, energía
uniform vec4 uS;   // ondas de choque: radio, amplitud, radio, amplitud
uniform vec4 uT;   // cálido, frío, agudos, glow
uniform vec4 uX;   // deriva, empuje, destello, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + vec2(1.3, -0.7);
    a *= 0.5;
  }
  return s;
}

float fbmLow(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + vec2(1.3, -0.7);
    a *= 0.5;
  }
  return s / 0.875 * 0.97;
}

// Ruido de crestas: filamentos finos y brillantes.
float ridged(vec2 p) {
  float s = 0.0;
  float a = 0.55;
  for (int i = 0; i < 4; i++) {
    float n = 1.0 - abs(noise(p) * 2.0 - 1.0);
    s += a * n * n;
    p = mat2(1.7, 1.1, -1.1, 1.7) * p + vec2(-2.1, 0.4);
    a *= 0.5;
  }
  return s;
}

float stars(vec2 uv, float scale, float threshold) {
  vec2 g = uv * scale;
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  float h = hash12(id);
  vec2 o = vec2(hash12(id + 3.1), hash12(id + 7.7)) - 0.5;
  float d = length(f - o * 0.7);
  float tw = 0.55 + 0.45 * sin(uA.x * (3.0 + 6.0 * uT.z) + h * 40.0);
  return smoothstep(0.09, 0.0, d) * step(threshold, h) * tw;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;
  float kick = uA.z;

  // Empuje de cámara con el golpe y onda de choque que curva la luz.
  uv /= 1.0 + 0.10 * uX.y;
  vec2 core = vec2(0.06, 0.04);
  vec2 rel = uv - core;
  float r = length(rel);
  float shock = uS.y * gauss((r - uS.x) * 9.0) + uS.w * gauss((r - uS.z) * 9.0);
  vec2 lens = rel / max(r, 0.001) * shock * 0.035;
  vec2 p = uv + lens;

  vec2 drift = vec2(uX.x * 0.6, uX.x * 0.25);
  vec2 q = p * 1.35 + drift;
  vec2 w = vec2(fbmLow(q + vec2(0.0, t * 0.04)), fbmLow(q + vec2(5.2, -t * 0.03)));
  w = (w - 0.5) * (1.4 + 0.45 * uA.y);
  float gas = fbm(q * 1.1 + w);
  float fil = ridged(q * 1.9 + w * 1.6 + vec2(t * 0.02, 0.0));
  float dust = smoothstep(0.50, 0.72, fbmLow(q * 1.6 + w * 0.8 + vec2(11.0, 3.0)));
  vec2 nearQ = p * 2.6 + drift * 1.8 + w * 0.5;
  float wisps = fbmLow(nearQ + vec2(t * 0.05, 0.0));

  // Color de emisión: dos gases que se mezclan, desplazados por el espectro.
  float mixer = smoothstep(0.25, 0.75, w.x * 0.5 + 0.5 + 0.35 * (uT.y - uT.x));
  vec3 emit = mix(uC1, uC2, mixer);
  float coreLight = (0.08 + 0.18 * uA.y + 0.9 * kick) / (0.015 + r * r * 5.0);
  float density = pow(clamp(gas * 1.35 - 0.25, 0.0, 1.0), 2.2);
  vec3 neb = emit * density * (0.45 + 0.22 * uA.y + 0.1 * uA.w);
  neb += mix(emit, uC3, 0.2) * pow(fil, 3.0) * density * (0.6 + 0.7 * uT.z + 0.15 * uA.y);
  neb *= 1.0 + coreLight * 0.25;
  neb += mix(emit, uC3, 0.5) * shock * density * 1.8;
  neb += uC2 * pow(clamp(wisps * 1.4 - 0.45, 0.0, 1.0), 2.0) * (0.12 + 0.25 * uA.y);

  vec3 col = uC0;
  float st = stars(p + drift * 0.2, 80.0, 0.975) + stars(p + drift * 0.5 + 7.0, 34.0, 0.988) * 1.6;
  col += vec3(0.9, 0.93, 1.0) * st * (1.0 - dust * 0.9) * (0.7 + 0.8 * uT.z);
  col += neb * (1.0 - 0.85 * dust) * uT.w;
  // Estrella joven en el núcleo con destello en cruz.
  float star = (0.0022 + 0.008 * kick + 0.002 * uA.y) / (r * r + 0.0008);
  float spikes = (0.0006 + 0.004 * kick) / (abs(rel.x * rel.y) * 30.0 + 0.0006) * exp(-r * 6.0);
  col += uC3 * (star + spikes) * (1.0 - 0.5 * dust);
  col += mix(uC2, uC3, 0.5) * uX.z * 0.08;

  col *= 1.0 - 0.4 * smoothstep(0.45, 1.25, length(uv * vec2(0.9, 0.7)));
  // Realce de croma: el gas conserva su color en los momentos intensos.
  float luma = dot(col, vec3(0.299, 0.587, 0.114));
  col = max(mix(vec3(luma), col, 1.35), 0.0);
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Bld { float x, w, h; };
  struct Win { float x, y; };
  struct Layer { std::vector<Bld> blds; std::vector<Win> wins;
                 float speed, shade, depth, height; };
  std::vector<Layer> layers;
  struct Drop { float x, y, v, len; };
  std::vector<Drop> drops;
  float lastw = 0, lasth = 0, lastDetail = -1.0f;
  static float hash01(int i, int salt) {
    float s = std::sin(float(i) * 12.9898f + float(salt) * 78.233f) * 43758.5453f;
    return s - std::floor(s);
  }
  void build(float w, float h, float detail) {
    float horizon = h * 0.66f;
    layers.clear();
    for (int li = 0; li < 4; li++) {
      Layer L;
      L.depth = float(li) / 3.0f;
      L.speed = 3.0f + L.depth * 22.0f;
      int sh = 10 + int((1.0f - L.depth) * 22.0f);
      L.shade = float(sh);
      L.height = horizon * (0.32f + L.depth * 0.66f);
      int steps = int(w / 30.0f) + 6;
      if (steps > 48) steps = 48;
      // El paso de la ventana escala con la altura de la capa: en pantallas
      // grandes el número de puntos se disparaba y reventaba el presupuesto
      // de 1 MiB de comandos del motor.
      float wyStep = std::max(9.0f, L.height / 40.0f);
      // El paso horizontal sigue a la pantalla para que el skyline siempre la
      // cubra entera, tenga el ancho que tenga.
      float xStep = w / float(steps);
      for (int i = 0; i < steps; i++) {
        Bld b;
        b.x = (float(i) + hash01(i, li) * 0.6f) * xStep;
        b.w = xStep * (0.5f + hash01(i, li + 91) * 1.5f) * (0.5f + L.depth * 0.5f);
        b.h = L.height * (0.28f + hash01(i, li + 173) * 0.72f);
        L.blds.push_back(b);
        if (L.depth > 0.35f) {
          float top = L.height - b.h;
          float wxStep = std::max(7.0f, b.w / 8.0f);
          for (float wy = 6.0f; wy < b.h - 8.0f; wy += wyStep) {
            for (float wx = 3.0f; wx < b.w - 6.0f; wx += wxStep) {
              if (hash01(int(wx) * 7 + int(wy) * 13, li + 311) > 0.62f)
                L.wins.push_back({b.x + wx, top + wy});
            }
          }
        }
      }
      layers.push_back(L);
    }
    int ndrops = int(380.0f * std::min(1.0f, std::max(0.4f, detail)));
    drops.clear(); drops.reserve(ndrops);
    for (int i = 0; i < ndrops; i++)
      drops.push_back({hash01(i, 7) * w, hash01(i, 29) * h,
        520.0f + hash01(i, 53) * 620.0f, 8.0f + hash01(i, 71) * 26.0f});
  }
  float rainTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    layers.clear(); drops.clear();
    rainTime = 0.0f; smoothEnergy = 0.0f; smoothBass = 0.0f;
    lastw = 0; lasth = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en una llovizna urbana tranquila (~0.12f).
    // Con música la lluvia y la ciudad cobran dinamismo y resplandor.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    rainTime += dt * f.speed * audioDrive;

    if (f.width != lastw || f.height != lasth || f.detail != lastDetail) {
      build(f.width, f.height, f.detail);
      lastw = f.width; lasth = f.height; lastDetail = f.detail;
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = rainTime;
    float horizon = h * 0.66f;
    float boost = std::clamp((0.85f + 0.35f * smoothEnergy) * f.intensity, 0.0f, 1.0f);
    Paint sky = Paint::linear({0, 0}, {0, h},
      {Color::argb(0xff05060c), Color::argb(0xff131a2c), Color::argb(0xff2a1c2c),
       Color::argb(0xff0a0c14), Color::argb(0xff04050a)}, {0, 0.42f, 0.63f, 0.67f, 1.0f});
    c.rect({0, 0, w, h}, sky);

    // Rótulos de neón con parpadeo eléctrico.
    const uint32_t neon[4] = {0xffff6a55, 0xff58c7f3, 0xff3fd8a5, 0xffffd166};
    Paint add; add.blend = Blend::plus;
    for (int i = 0; i < 7; i++) {
      float ph = float(i) * 1.7f;
      float flick = 0.55f + 0.45f * std::sin(t * 44.0f + ph) * std::sin(t * 14.0f + ph * 2.0f);
      if (flick < 0.06f) flick = 0.06f;
      if (flick > 1.0f) flick = 1.0f;
      Color cc = Color::argb(neon[i % 4]);
      add.color = {cc.r, cc.g, cc.b, flick * 0.85f * boost};
      int sw = int(w) - 90; if (sw < 1) sw = 1;
      int shh = int(horizon * 0.5f); if (shh < 1) shh = 1;
      float x = float((i * 137) % sw) + 30.0f;
      float y = horizon - 40.0f - float((i * 211) % shh);
      c.rect({x, y, 8.0f + float((i * 7) % 26), 18.0f + float((i * 13) % 54)}, add);
    }

    // 1. Ciudad en capas (sin clip innecesario).
    for (size_t li = 0; li < layers.size(); li++) {
      const Layer& L = layers[li];
      float period = std::max(w, 1.0f);
      float off = std::fmod(t * L.speed, period);
      float alpha = 0.35f + L.depth * 0.65f;
      for (int rep = 0; rep < 2; rep++) {
        float dx = -off + float(rep) * period;
        Path body;
        for (const auto& b : L.blds)
          body.rect({dx + b.x, L.height - b.h, b.w - 2.0f, b.h});
        Paint fill;
        fill.color = {L.shade / 255.0f, (L.shade + 3.0f) / 255.0f,
          (L.shade + 10.0f) / 255.0f, alpha};
        c.path(body, fill);
        if (!L.wins.empty()) {
          std::vector<Vec2> win;
          win.reserve(L.wins.size() * 2);
          for (const auto& p : L.wins) {
            win.push_back({dx + p.x, p.y});
            win.push_back({dx + p.x, p.y});
          }
          Paint wp; wp.blend = Blend::plus;
          wp.color = {1, 0.851f, 0.627f, 0.5f * alpha * boost};
          c.points(win, 1.7f, wp);
        }
      }
    }

    // 2. Reflejo mojado invertido (un solo clip para todas las capas combinadas).
    c.save();
    Path refClip;
    refClip.rect({0, horizon, w, h - horizon});
    c.clip(refClip);
    c.translate(0, horizon);
    c.scale(1, -0.42f);
    c.translate(0, -horizon);
    for (size_t li = 0; li < layers.size(); li++) {
      const Layer& L = layers[li];
      float period = std::max(w, 1.0f);
      float off = std::fmod(t * L.speed, period);
      float alpha = (0.35f + L.depth * 0.65f) * 0.2f;
      for (int rep = 0; rep < 2; rep++) {
        float dx = -off + float(rep) * period;
        Path body;
        for (const auto& b : L.blds)
          body.rect({dx + b.x, L.height - b.h, b.w - 2.0f, b.h});
        Paint fill;
        fill.color = {L.shade / 255.0f, (L.shade + 3.0f) / 255.0f,
          (L.shade + 10.0f) / 255.0f, alpha};
        c.path(body, fill);
        if (!L.wins.empty()) {
          std::vector<Vec2> win;
          win.reserve(L.wins.size() * 2);
          for (const auto& p : L.wins) {
            win.push_back({dx + p.x, p.y});
            win.push_back({dx + p.x, p.y});
          }
          Paint wp; wp.blend = Blend::plus;
          wp.color = {1, 0.851f, 0.627f, 0.1f * (0.35f + L.depth * 0.65f) * boost};
          c.points(win, 1.7f, wp);
        }
      }
    }
    c.restore();

    // Niebla en el horizonte.
    float fogTop = horizon - h * 0.18f;
    Paint fog = Paint::linear({0, fogTop}, {0, fogTop + h * 0.22f},
      {{0.47f, 0.314f, 0.408f, 0}, {0.588f, 0.373f, 0.471f, 0.6f * boost}});
    c.rect({0, fogTop, w, h * 0.22f}, fog);

    // Lluvia: un solo Path con un segmento por gota.
    Path rain;
    float wind = std::sin(t * 0.23f) * 40.0f;
    for (const auto& d : drops) {
      float y = std::fmod(d.y + t * d.v, h + 60.0f) - 20.0f;
      float x = std::fmod(d.x + wind * (y / h), w);
      if (x < 0) x += w;
      rain.moveTo(x, y);
      rain.lineTo(x - wind * 0.02f, y + d.len);
    }
    Paint rp; rp.blend = Blend::plus;
    rp.color = {0.745f, 0.843f, 1, 0.42f * boost};
    rp.strokeWidth = 1.0f; rp.strokeCap = 1; rp.strokeJoin = 1;
    c.path(rain, rp);
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float phase = 0, swirl = 0, hue = 0;
  std::array<float, 4> rings{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 20.0f;
    swirl = rng.unit() * 6.0f;
    hue = 0;
    rings = {3.0f, 0.0f, 3.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 10.0f, 2.5f, dt);
    spark = follow(spark, m.spark, 25.0f, 6.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      rings[2] = rings[0];
      rings[3] = rings[1];
      rings[0] = 0.0f;
      rings[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 7.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      rings[i] += dt * (0.55f + 0.35f * drive);
      rings[i + 1] *= std::exp(-dt * 1.4f);
    }

    phase += dt * f.speed * (0.18f + 0.9f * drive + 0.7f * kick);
    swirl += dt * f.speed * (0.10f + 1.4f * bass + 0.8f * kick);
    hue += dt * (0.02f + 0.25f * body);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {phase, swirl, bass * amp, kick * amp});
    u.insert(u.end(), {rings[0], rings[1] * amp, rings[2], rings[3] * amp});
    u.insert(u.end(), {hue, spark * amp, energy, f.glow});
    u.insert(u.end(), {flash, 0.6f + 0.4f * f.detail, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("film", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.film:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, remolino, graves, golpe
uniform vec4 uR;   // anillos: radio, amplitud, radio, amplitud
uniform vec4 uM;   // tono, agudos, energía, glow
uniform vec4 uX;   // destello, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s;
}

float fbmLow(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875 * 0.94;
}

vec2 rotate(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float t = uA.x;
  float r = length(p);

  // Remolinos: el dominio gira alrededor de tres vórtices que derivan.
  vec2 q = p;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    vec2 c = vec2(sin(t * 0.13 + fi * 2.1), cos(t * 0.11 + fi * 1.7)) * vec2(0.32, 0.45);
    vec2 d = q - c;
    float w = exp(-dot(d, d) * 9.0);
    q = c + rotate(d, w * (1.2 + 0.9 * sin(uA.y * 0.35 + fi)) * (0.6 + uA.z * 1.6));
  }
  vec2 warp = vec2(fbmLow(q * 1.7 + vec2(0.0, t * 0.06)), fbmLow(q * 1.7 + vec2(5.2, -t * 0.05)));
  vec2 s = q + (warp - 0.5) * (0.55 + 0.6 * uA.z);
  float detail = fbm(s * (2.6 + 1.6 * uX.y) + vec2(t * 0.03, -t * 0.09));
  float fine = noise(s * 14.0 + vec2(0.0, -t * 0.5)) - 0.5;

  // Grosor (nm): la película drena hacia abajo; los graves la adelgazan en el centro.
  float thickness = 230.0 + 300.0 * smoothstep(0.55, -0.6, p.y);
  thickness += (detail - 0.5) * (330.0 + 220.0 * uA.z);
  thickness += fine * (18.0 + 80.0 * uM.y);
  thickness -= uA.z * 170.0 * exp(-r * r * 5.0);
  thickness += uR.y * 240.0 * gauss((r - uR.x) * 9.0);
  thickness += uR.w * 190.0 * gauss((r - uR.z) * 9.0);
  thickness += 80.0 * sin(uM.x * 6.2831853);
  // Película negra en la zona más fina, como en una pompa real.
  float black = smoothstep(120.0, 230.0, thickness);
  thickness = max(thickness, 0.0);

  // Color iridiscente: ciclo de tono por grosor, más vivo en los primeros órdenes.
  float order = thickness * 0.0029;
  vec3 iri = 0.5 + 0.5 * cos(6.2831853 * (order + vec3(0.0, 0.33, 0.67)));
  iri = pow(iri, vec3(1.5));
  float fadeOrders = exp(-thickness / 1100.0);
  vec3 film = iri * black * (0.55 + 0.75 * fadeOrders);
  // La luz que refleja la película varía a gran escala: zonas brillantes y oscuras.
  float sheen = 0.12 + 1.25 * smoothstep(0.35, 0.8, fbmLow(p * 0.9 + vec2(t * 0.02, 1.7)));
  float light = (0.24 + 0.15 * uM.z + 0.40 * uA.w) * sheen;
  vec3 col = uC0 + film * light * uM.w;

  // Arco especular suave: reflejo de una luz de anillo sobre la película.
  vec2 hp = p - vec2(-0.05, 0.10);
  float arc = gauss((length(hp * vec2(1.0, 1.25)) - 0.42) / 0.035);
  arc *= smoothstep(-0.2, 0.6, hp.y + hp.x * 0.3);
  col += uC3 * arc * (0.10 + 0.35 * uX.x + 0.25 * uA.w) * (0.6 + 0.4 * sheen);

  // Halo de color que acompaña a los anillos del golpe.
  col += mix(uC1, uC2, 0.5 + 0.5 * sin(t)) * uR.y * 0.25 * gauss((r - uR.x) * 6.0);

  col *= 1.0 - 0.45 * smoothstep(0.45, 1.3, length(p * vec2(0.85, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, push = 0;
  std::array<float, 8> bands{};
  float spin = 0, orbit = 0, storm = 0;
  std::array<float, 4> waves{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = push = 0;
    bands.fill(0);
    spin = rng.unit() * 6.2831853f;
    orbit = rng.unit() * 0.6f - 0.3f;
    storm = rng.unit() * 10.0f;
    waves = {3.0f, 0.0f, 3.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      waves[2] = waves[0];
      waves[3] = waves[1];
      waves[0] = 0.0f;
      waves[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 4.5f), hit);
    flash = std::max(flash * std::exp(-dt * 6.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      waves[i] += dt * 1.1f;
      waves[i + 1] *= std::exp(-dt * 1.3f);
    }

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 18.0f, 3.5f, dt);
    }

    spin += dt * f.speed * (0.04f + 0.25f * drive + 0.3f * kick);
    orbit += dt * f.speed * (0.015f + 0.05f * drive);
    storm += dt * f.speed * (0.05f + 0.6f * bass);
    push = follow(push, kick, 14.0f, 2.2f, dt);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {spin, orbit, storm, push * amp});
    u.insert(u.end(), {bass * amp, kick * amp, energy, spark * amp});
    u.insert(u.end(), {waves[0], waves[1] * amp, waves[2], waves[3] * amp});
    u.insert(u.end(), {bands[0], bands[1], bands[2], bands[3]});
    u.insert(u.end(), {bands[4], bands[5], bands[6], bands[7]});
    u.insert(u.end(), {flash, f.glow, f.detail, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("planet", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.planet:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // giro del planeta, órbita de cámara, tormentas, empuje
uniform vec4 uB;   // graves, golpe, energía, agudos
uniform vec4 uW;   // ondas en los anillos: radio, amplitud, radio, amplitud
uniform vec4 uBands0;
uniform vec4 uBands1;
uniform vec4 uX;   // destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

const float RING_IN = 1.38;
const float RING_OUT = 2.45;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float hash13(vec3 p3) {
  p3 = fract(p3 * 0.1031);
  p3 += dot(p3, p3.zyx + 31.32);
  return fract((p3.x + p3.y) * p3.z);
}

float noise3(vec3 x) {
  vec3 i = floor(x);
  vec3 f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x),
                 mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
             mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x),
                 mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}

float fbm3(vec3 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise3(p);
    p = p * 2.07 + vec3(3.1, 1.7, -2.3);
    a *= 0.5;
  }
  return s;
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  return mix(hash12(vec2(i, 1.7)), hash12(vec2(i + 1.0, 1.7)), f * f * (3.0 - 2.0 * f));
}

float pick(float i) {
  if (i < 0.5) return uBands0.x;
  if (i < 1.5) return uBands0.y;
  if (i < 2.5) return uBands0.z;
  if (i < 3.5) return uBands0.w;
  if (i < 4.5) return uBands1.x;
  if (i < 5.5) return uBands1.y;
  if (i < 6.5) return uBands1.z;
  return uBands1.w;
}

float bandAt(float x) {
  float m = clamp(x, 0.0, 1.0) * 7.0;
  float i = floor(m);
  return mix(pick(i), pick(min(i + 1.0, 7.0)), smoothstep(0.0, 1.0, m - i));
}

// Densidad de los anillos: divisiones, huecos y ondas del golpe.
float ringDensity(float rho) {
  float inside = smoothstep(RING_IN, RING_IN + 0.06, rho) * smoothstep(RING_OUT, RING_OUT - 0.08, rho);
  float fine = 0.55 + 0.45 * noise1(rho * 46.0) * (0.7 + 0.3 * sin(rho * 180.0));
  float coarse = 0.6 + 0.4 * noise1(rho * 9.0 + 3.0);
  float gap = 1.0 - 0.92 * smoothstep(0.035, 0.0, abs(rho - 1.97));
  gap *= 1.0 - 0.6 * smoothstep(0.02, 0.0, abs(rho - 2.28));
  return inside * fine * coarse * gap;
}

vec3 rotateAxis(vec3 v, vec3 k, float a) {
  return v * cos(a) + cross(k, v) * sin(a) + k * dot(k, v) * (1.0 - cos(a));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;

  vec3 axis = normalize(vec3(0.42, 1.0, 0.12));
  float az = 0.55 + uA.y;
  float el = 0.30;
  float dist = 6.2 - 0.9 * uA.w;
  vec3 ro = dist * vec3(cos(el) * sin(az), sin(el), -cos(el) * cos(az));
  vec3 fw = normalize(-ro);
  vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));
  vec3 up = cross(fw, rt);
  vec3 rd = normalize(fw * 2.0 + rt * uv.x + up * (uv.y + 0.04));
  vec3 sun = normalize(vec3(-0.8, 0.62, -0.35));
  float kick = uB.y;

  // Fondo: estrellas, polvo galáctico y resplandor del sol fuera de cuadro.
  vec3 col = uC0;
  vec2 g = uv * 110.0;
  float h = hash12(floor(g));
  float star = smoothstep(0.985, 1.0, h) * smoothstep(0.35, 0.0, length(fract(g) - 0.5));
  col += vec3(0.9, 0.93, 1.0) * star * (0.6 + 0.6 * sin(uA.x * 3.0 + h * 50.0) * uB.w + 0.4);
  col += uC2 * 0.05 * exp(-abs(uv.y + uv.x * 0.6 - 0.15) * 5.0);
  float sunGlow = pow(max(dot(rd, sun), 0.0), 12.0);
  col += uC3 * sunGlow * (0.15 + 0.2 * uX.x);

  // Planeta.
  float b = dot(ro, rd);
  float c = dot(ro, ro) - 1.0;
  float disc = b * b - c;
  float tP = disc > 0.0 ? -b - sqrt(disc) : 1e9;

  // Plano de los anillos.
  float denom = dot(rd, axis);
  float tR = abs(denom) > 1e-4 ? -dot(ro, axis) / denom : -1.0;
  vec3 hp = ro + rd * tR;
  float rho = length(hp);
  bool ringHit = tR > 0.0 && rho > RING_IN && rho < RING_OUT;

  if (tP < 1e8) {
    vec3 pos = ro + rd * tP;
    vec3 n = normalize(pos);
    float lat = dot(n, axis);
    vec3 nr = rotateAxis(n, axis, uA.x);
    float turb = fbm3(nr * vec3(2.2, 6.5, 2.2) + vec3(0.0, 0.0, uA.z * 0.15));
    float latw = lat + (turb - 0.5) * (0.07 + 0.06 * uB.x);
    float band = noise1(latw * 14.0 + 4.0) * 0.6 + noise1(latw * 37.0) * 0.4;
    vec3 surf = mix(uC1 * 0.65, uC3, smoothstep(0.2, 0.8, band));
    surf *= 0.85 + 0.3 * noise1(latw * 70.0 + 2.0);
    surf = mix(surf, mix(uC2, uC3, 0.5), smoothstep(0.62, 0.9, noise1(latw * 5.0 + 9.0)) * 0.25);
    // Gran tormenta ovalada que gira con el planeta.
    vec3 spotDir = normalize(vec3(0.62, -0.30, 0.72));
    vec3 sd = (nr - spotDir) * vec3(1.0, 2.4, 1.0);
    float spot = length(sd);
    surf = mix(surf, mix(uC1, uC3, 0.25) * 1.1, smoothstep(0.20, 0.12, spot));
    surf *= 1.0 - 0.35 * gauss((spot - 0.2) / 0.03);
    float diff = clamp(dot(n, sun) * 0.9 + 0.1, 0.0, 1.0);
    // Sombra de los anillos sobre el planeta.
    float ts = -dot(pos, axis) / dot(sun, axis);
    float shade = 1.0;
    if (ts > 0.0) {
      float rs = length(pos + sun * ts);
      shade = 1.0 - 0.75 * ringDensity(rs);
    }
    float limb = mix(0.5, 1.0, pow(max(dot(n, -rd), 0.0), 0.4));
    vec3 lit = surf * diff * shade * limb * 1.3;
    lit += surf * 0.03;
    float limbGlow = pow(1.0 - max(dot(n, -rd), 0.0), 5.0);
    lit += uC2 * limbGlow * (0.5 + 0.6 * uB.x + 0.9 * kick) * (0.3 + 0.7 * diff) * uX.y;
    // Óvalo auroral alrededor del polo, con cortinas suaves.
    float oval = gauss((abs(lat) - 0.86) / 0.035);
    float curtain = 0.4 + 0.6 * noise3(nr * 14.0 + vec3(0.0, uA.z * 0.8, 0.0));
    lit += mix(uC2, vec3(0.4, 1.0, 0.7), 0.5) * oval * curtain * (1.0 - diff) * (0.05 + 1.2 * kick) * uX.y;
    col = lit;
  }

  if (ringHit && tR < tP) {
    float dens = ringDensity(rho);
    float x = (rho - RING_IN) / (RING_OUT - RING_IN);
    float eq = bandAt(x);
    float wave = uW.y * gauss((rho - RING_IN - uW.x) * 10.0) +
                 uW.w * gauss((rho - RING_IN - uW.z) * 10.0);
    // Sombra del planeta sobre los anillos.
    float bb = dot(hp, sun);
    float cc = dot(hp, hp) - 1.0;
    float shadow = (bb < 0.0 && bb * bb - cc > 0.0) ? 0.12 : 1.0;
    float light = 0.45 + 0.55 * abs(dot(sun, axis));
    vec3 ringCol = mix(uC3, mix(uC1, uC2, x), 0.25 + 0.35 * eq);
    float glint = smoothstep(0.975, 1.0, hash12(floor(vec2(rho * 260.0, atan(hp.z, hp.x) * 140.0)) +
                                                floor(uA.x * 4.0))) * uB.w;
    // El ecualizador: cada banda enciende su anillo con un color propio.
    vec3 eqCol = mix(uC2, uC1, smoothstep(0.0, 1.0, x));
    vec3 rc = ringCol * dens * light * shadow * (0.5 + 0.3 * eq) +
              eqCol * dens * (eq * eq * 0.9 + wave * 1.6) +
              vec3(1.0) * glint * dens * 0.8;
    float alpha = clamp(dens * (0.75 + 0.25 * eq), 0.0, 0.95);
    col = mix(col, rc, alpha);
  }

  col += uC3 * uX.x * 0.12 * exp(-abs(uv.y - 0.3) * 18.0);
  col *= 1.0 - 0.35 * smoothstep(0.5, 1.3, length(uv * vec2(0.85, 0.7)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

