class Visual final : public Scene {
  struct Seg { float x1, y1, x2, y2; int level; };
  struct Spore { float x, y, speed, phase; };
  std::vector<Seg> segs[10];
  std::vector<Vec2> tips;
  std::vector<Spore> spores;
  float treeTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float motion = 1.0f;
  void grow(float x, float y, float a, float len, int d, float seed, float t) {
    float sway = std::sin(seed * 0.7f + t * 0.25f) * float(9 - d) * 0.025f * motion;
    float na = a + sway;
    float x2 = x + std::cos(na) * len, y2 = y + std::sin(na) * len;
    segs[9 - d].push_back({x, y, x2, y2, 9 - d});
    if (d <= 1) {
      if (tips.size() < 256) tips.push_back({x2, y2});
      return;
    }
    float spread = 0.42f + std::sin(t * 0.4f + seed) * 0.07f;
    grow(x2, y2, na - spread, len * 0.74f, d - 1, seed * 2.0f + 1.0f, t);
    grow(x2, y2, na + spread, len * 0.74f, d - 1, seed * 2.0f + 2.0f, t);
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    spores.clear(); motion = 1.0f;
    treeTime = 0.0f; smoothEnergy = 0.0f; smoothBass = 0.0f;
    for (int i = 0; i < 70; i++)
      spores.push_back({rng.unit(), rng.unit(), 0.3f + rng.unit() * 1.2f, rng.unit() * 6.2831853f});
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un vaivén suave y meditativo (~0.12f).
    // Con música la selva bioluminiscente respira y late con el audio.
    float audioDrive = 0.12f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    treeTime += dt * f.speed * audioDrive;

    float t = treeTime;
    motion = f.reducedMotion ? 0.3f : 1.0f;
    for (int i = 0; i < 10; i++) segs[i].clear();
    tips.clear();
    grow(f.width * 0.5f, f.height * 0.94f, -1.5707963f, f.height * (0.16f + smoothBass * 0.035f), 9, 1.0f, t);
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = treeTime;
    float boost = std::clamp((0.8f + 0.4f * smoothEnergy + 0.3f * smoothBass) * f.intensity, 0.0f, 1.0f);
    Paint bg = Paint::radial({w * 0.5f, h * 0.75f}, h * 0.9f,
      {Color::argb(0xff04231c), Color::argb(0xff021410), Color::argb(0xff000705)}, {0, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);
    std::vector<Vec2> sbuf; sbuf.reserve(spores.size());
    for (const auto& s : spores) {
      float y = std::fmod(s.y * h - t * s.speed * 9.0f, h);
      if (y < 0) y += h;
      sbuf.push_back({s.x * w + std::sin(t * 0.6f + s.phase) * 12.0f, y});
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.435f, 1, 0.753f, 0.4f * boost};
    c.points(sbuf, 1.0f, sp);
    const uint32_t cols[10] = {0xff0b3a2e, 0xff0f5c42, 0xff14855a, 0xff1fb573, 0xff43e08f,
      0xff7bffb0, 0xffb9ffd6, 0xffe6fff1, 0xffffffff, 0xffffffff};
    for (int i = 0; i < 10; i++) {
      Path path;
      for (const auto& s : segs[i]) {
        path.moveTo(s.x1, s.y1); path.lineTo(s.x2, s.y2);
      }
      Paint p; p.blend = Blend::plus;
      Color cc = Color::argb(cols[i]);
      p.color = {cc.r, cc.g, cc.b, 0.85f * boost};
      p.strokeWidth = std::max(0.6f, float(9 - i) * 0.52f);
      c.path(path, p);
    }
    Paint tp; tp.blend = Blend::plus;
    tp.color = {0.788f, 1, 0.902f, (0.45f + 0.45f * std::abs(std::sin(t * 2.0f))) * boost};
    c.points(tips, 1.6f, tp);
  }
};

class Visual final : public Scene {
  struct Fan { float axis, spread, spreadVel, power, hue, hueGoal; };
  std::array<Fan, 4> fans{};
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, mids = 0, highs = 0, lows = 0;
  float phase = 0, haze = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    for (int i = 0; i < 4; i++) {
      float h = float(i) / 3.0f + rng.unit() * 0.1f;
      fans[i] = {0.0f, 0.4f, 0.0f, 0.0f, h, h};
    }
    bass = body = spark = energy = slowBass = kick = flash = drive = mids = highs = lows = 0;
    phase = rng.unit() * 20.0f;
    haze = rng.unit() * 10.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float lo = 0, mi = 0, hi = 0;
    for (int i = 0; i < 9; i++) lo = std::max(lo, m.smoothSpectrum[i]);
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    for (int i = 21; i < 31; i++) hi = std::max(hi, m.smoothSpectrum[i]);
    lows = follow(lows, lo, 20.0f, 4.0f, dt);
    mids = follow(mids, mi, 20.0f, 4.0f, dt);
    highs = follow(highs, hi, 20.0f, 4.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.5f), hit);
    flash = std::max(flash * std::exp(-dt * 9.0f), std::min(fl, 1.0f));

    phase += dt * f.speed * (0.25f + 1.2f * drive + 0.5f * kick);
    haze += dt * f.speed * (0.15f + 0.3f * drive);

    // Coreografía: barridos suaves; el lateral derecho es espejo del izquierdo.
    float sweepA = std::sin(phase * 0.6f) * 0.55f;
    float sweepB = 0.62f + std::sin(phase * 0.8f + 1.0f) * 0.42f;
    float sweepD = 3.14159265f + std::sin(phase * 0.5f + 2.0f) * 0.6f;
    float axisGoal[4] = {sweepA, sweepB, -sweepB, sweepD};
    float spreadBase[4] = {0.45f + 0.55f * lows, 0.35f + 0.45f * mids, 0.35f + 0.45f * highs, 0.8f};
    float powerGoal[4] = {0.35f + 1.1f * lows + 0.6f * kick,
                          0.22f + 1.0f * mids + 0.5f * kick,
                          0.22f + 1.0f * highs + 0.5f * kick,
                          (0.9f * drive + 0.7f * kick) * (m.active ? 1.0f : 0.0f)};
    for (int i = 0; i < 4; i++) {
      Fan& fan = fans[i];
      fan.axis += (axisGoal[i] - fan.axis) * (1.0f - std::exp(-dt * 6.0f));
      if (strike) {
        fan.spreadVel += 3.2f * hit;
        fan.hueGoal += 1.0f / 3.0f;
      }
      // Muelle: el abanico se abre con el golpe y vuelve a su apertura base.
      float target = spreadBase[i];
      fan.spreadVel += ((target - fan.spread) * 40.0f - fan.spreadVel * 7.0f) * dt;
      fan.spread = std::clamp(fan.spread + fan.spreadVel * dt, 0.05f, 2.6f);
      fan.power = follow(fan.power, powerGoal[i], 18.0f, 4.0f, dt);
      fan.hue += (fan.hueGoal - fan.hue) * (1.0f - std::exp(-dt * 10.0f));
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    const float counts[4] = {9.0f, 7.0f, 7.0f, 9.0f};
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    for (int i = 0; i < 4; i++)
      u.insert(u.end(), {fans[i].axis, fans[i].spread, counts[i], std::min(fans[i].power * amp, 2.0f)});
    u.insert(u.end(), {fans[0].hue, fans[1].hue, fans[2].hue, fans[3].hue});
    u.insert(u.end(), {spark * amp, flash, f.glow, haze});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("lasers", {0, 0, f.width, f.height}, u);
  }
};

