      float angle = float(i) * angleStep - 3.14159265f * 0.5f;

      // Frecuencia normalizada (sub-graves simétricos y agudos laterales)
      float normFreq = std::abs((float(i) / (float(kBarCount) * 0.5f)) - 1.0f);
      int specIdx = std::clamp(int(normFreq * 30.0f), 0, 30);
      float realAudio = f.music.active ? f.music.spectrum[specIdx] : 0.0f;
      float smoothAudio = f.music.active ? f.music.smoothSpectrum[specIdx] : 0.0f;

      // En silencio las barras descansan en un anillo limpio sin brincar a lo loco
      float barVal = f.music.active ? std::max(realAudio * 1.8f, smoothAudio * 1.3f) : 0.015f;
      float barLength = minDim * (0.018f + barVal * 0.18f + kick * (1.0f - normFreq) * 0.12f);

      float cosA = std::cos(angle), sinA = std::sin(angle);
      float sx = center.x + baseRadius * cosA;
      float sy = center.y + baseRadius * sinA;
      float ex = center.x + (baseRadius + barLength) * cosA;
      float ey = center.y + (baseRadius + barLength) * sinA;

      // Color lerp: cian {0, 1, 0.88} a magenta {1, 0, 0.33}
      Color barCol{
        0.0f * (1.0f - normFreq) + 1.0f * normFreq,
        1.0f * (1.0f - normFreq) + 0.0f * normFreq,
        0.88f * (1.0f - normFreq) + 0.33f * normFreq,
        std::clamp(0.85f * f.intensity, 0.0f, 1.0f)
      };
      Paint bp; bp.blend = Blend::plus; bp.color = barCol;
      bp.strokeWidth = std::max(1.2f, minDim * 0.008f);
      bp.strokeCap = 1;

      Path barPath; barPath.moveTo(sx, sy); barPath.lineTo(ex, ey);
      c.path(barPath, bp);

      // Chispas en los picos de energía
      if (barLength > minDim * 0.14f) {
        float spx = center.x + (baseRadius + barLength + 4.0f) * cosA;
        float spy = center.y + (baseRadius + barLength + 4.0f) * sinA;
        sparkCaps.push_back({spx, spy});
      }
    }

    if (!sparkCaps.empty()) {
      Paint spk; spk.blend = Blend::plus;
      spk.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * f.intensity, 0.0f, 1.0f)};
      c.points(sparkCaps, 2.0f, spk);
    }

    // 3. Anillo de resonancia exterior
    float ringRadius = baseRadius + minDim * 0.22f;
    Paint ringPaint; ringPaint.blend = Blend::plus;
    ringPaint.color = {0.0f, 1.0f, 0.88f, std::clamp(0.25f * f.intensity, 0.0f, 1.0f)};
    ringPaint.strokeWidth = 1.4f;
    c.circle(center, ringRadius, ringPaint);

    // 4. Partículas armónicas en órbita
    std::vector<Vec2> orbiters;
    orbiters.reserve(8);
    for (int p = 0; p < 8; p++) {
      float pAngle = t * (0.8f + float(p) * 0.2f) + float(p) * (3.14159265f / 4.0f);
      float radOffset = std::sin(pAngle * 3.0f) * 12.0f;
      float ox = center.x + (ringRadius + radOffset) * std::cos(pAngle);
      float oy = center.y + (ringRadius + radOffset) * std::sin(pAngle);
      orbiters.push_back({ox, oy});
    }
    Paint orbPaint; orbPaint.blend = Blend::plus;
    orbPaint.color = {1.0f, 0.0f, 0.63f, std::clamp(0.85f * f.intensity, 0.0f, 1.0f)};
    c.points(orbiters, 2.8f, orbPaint);
  }
};

class Visual final : public Scene {
  static constexpr int kNodeCount = 750;
  static constexpr float kGoldenAngle = 2.39996323f; // ~137.507764 grados
  float spiralAngle = 0.0f;
  float colorTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;

  static Color hsvToRgb(float h, float s, float v, float a) {
    float c = v * s;
    float x = c * (1.0f - std::abs(std::fmod(h / 60.0f, 2.0f) - 1.0f));
    float m = v - c;
    float r = 0, g = 0, b = 0;
    if (h < 60.0f) { r = c; g = x; b = 0; }
    else if (h < 120.0f) { r = x; g = c; b = 0; }
    else if (h < 180.0f) { r = 0; g = c; b = x; }
    else if (h < 240.0f) { r = 0; g = x; b = c; }
    else if (h < 300.0f) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }
    return Color{
      std::clamp(r + m, 0.0f, 1.0f),
      std::clamp(g + m, 0.0f, 1.0f),
      std::clamp(b + m, 0.0f, 1.0f),
      std::clamp(a, 0.0f, 1.0f)
    };
  }

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    spiralAngle = 0.0f;
    colorTime = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un giro áureo meditativo (~0.05f).
    // Con música la espiral acelera y desata ondas cromáticas al ritmo.
    float rate = 0.05f + smoothEnergy * 0.35f + smoothBass * 0.20f;
    spiralAngle += dt * f.speed * rate;
    colorTime += dt * f.speed * (0.08f + smoothEnergy * 0.72f);
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    Vec2 center{w * 0.5f, h * 0.5f};
    float minDim = std::min(w, h);
    float maxDim = std::max(w, h);

    // 1. Fondo cósmico profundo
    Paint bg = Paint::radial(center, minDim * 0.85f,
      {Color::argb(0xff0f001a), Color::argb(0xff040008), Color::argb(0xff000000)},
      {0.0f, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Resplandor de la singularidad central
    float bassBreath = 1.0f + smoothBass * 0.32f;
    Paint singGlow = Paint::radial(center, 40.0f * bassBreath,
      {{0.0f, 1.0f, 0.84f, std::clamp(0.40f * f.intensity, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    singGlow.blend = Blend::plus;
    c.circle(center, 40.0f * bassBreath, singGlow);

    // 2. Nodos de la filotaxis áurea
    float cConst = (minDim * 0.021f) * bassBreath;
    float maxRadius = maxDim * 0.72f;

    for (int n = 1; n < kNodeCount; n++) {
      float fn = float(n);
      float theta = fn * kGoldenAngle + spiralAngle;
      float r = cConst * std::sqrt(fn);
      if (r > maxRadius) break;

      float px = center.x + r * std::cos(theta);
      float py = center.y + r * std::sin(theta);

      float hue = std::fmod(fn * 0.45f + colorTime * 25.0f, 360.0f);
      if (hue < 0.0f) hue += 360.0f;
      float alpha = std::clamp((0.40f + (fn / float(kNodeCount)) * 0.60f) * f.intensity, 0.0f, 1.0f);

      Color nodeCol = hsvToRgb(hue, 0.85f, 1.0f, alpha);
      Paint np; np.blend = Blend::plus; np.color = nodeCol;
      float nodeRad = (1.4f + std::sqrt(fn / float(kNodeCount)) * 2.6f) * (minDim / 400.0f);

      c.circle({px, py}, std::max(0.6f, nodeRad), np);
    }

    // 3. Singularidad blanca en el origen
    Paint singCenter; singCenter.blend = Blend::plus;
    singCenter.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * f.intensity, 0.0f, 1.0f)};
    c.circle(center, 3.5f, singCenter);
  }
};

class Visual final : public Scene {
  static constexpr int kParticleCount = 360;
  struct StellarParticle {
    float x, y, vx, vy, energy, size;
    int colIdx;
  };
  std::vector<StellarParticle> particles;
  int done = 0;
  float fenergy = 0.0f, fbass = 0.0f;
  bool fActive = false;
  float shockRadius = 0.0f;

  void step(float w, float h) {
    const float dt = 1.0f / 60.0f;
    float cx = w * 0.5f, cy = h * 0.5f;

    // Disparo de ondas de choque exclusivamente ante bombos reales con música activa
    if (shockRadius > 0.0f) {
      shockRadius += 16.0f;
      if (shockRadius > std::max(w, h) * 1.2f) {
        shockRadius = 0.0f;
      }
    } else if (fActive && fbass > 0.65f) {
      shockRadius = 10.0f;
      float blast = 14.0f + fenergy * 18.0f;
      for (auto& p : particles) {
        float dx = p.x - cx, dy = p.y - cy;
        float dist = std::max(12.0f, std::sqrt(dx * dx + dy * dy));
        float angle = std::atan2(dy, dx);
        float speed = std::clamp(blast * 110.0f / dist, 3.0f, 26.0f);
        p.vx = std::cos(angle) * speed;
        p.vy = std::sin(angle) * speed;
        p.energy = 1.0f;
      }
    }

    for (auto& p : particles) {
      // Gravedad central suave
      float dx = cx - p.x;
      float dy = cy - p.y;
      float dist = std::max(30.0f, std::sqrt(dx * dx + dy * dy));
      float grav = 0.07f;
      float perpX = -dy / dist;
      float perpY = dx / dist;

      p.vx += (dx / dist) * grav + perpX * 0.035f;
      p.vy += (dy / dist) * grav + perpY * 0.035f;

      p.vx *= 0.985f;
      p.vy *= 0.985f;

      p.x += p.vx * dt * 60.0f;
      p.y += p.vy * dt * 60.0f;

      if (p.x < 0.0f) { p.x = 0.0f; p.vx = -p.vx * 0.6f; }
      if (p.x > w) { p.x = w; p.vx = -p.vx * 0.6f; }
      if (p.y < 0.0f) { p.y = 0.0f; p.vy = -p.vy * 0.6f; }
      if (p.y > h) { p.y = h; p.vy = -p.vy * 0.6f; }

      p.energy = std::clamp(p.energy * 0.993f, 0.15f, 1.0f);
    }
    done++;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    particles.clear(); particles.reserve(kParticleCount);
    done = 0; shockRadius = 0.0f; fActive = false; fenergy = 0.0f; fbass = 0.0f;
    for (int i = 0; i < kParticleCount; i++) {
      float a = rng.unit() * 6.2831853f;
      float dist = 20.0f + rng.unit() * 180.0f;
      float spd = (rng.unit() - 0.5f) * 2.2f;
      particles.push_back({
        std::cos(a) * dist, std::sin(a) * dist,
        std::sin(a) * spd, -std::cos(a) * spd,
        rng.unit(),
        1.2f + rng.unit() * 2.2f,
        int(rng.unit() * 4.999f)
      });
    }
  }

  void update(const Frame& f) override {
    fActive = f.music.active;
    fenergy = f.music.active ? f.music.energy : 0.0f;
    fbass = f.music.active ? f.music.bass : 0.0f;
    float rate = (f.reducedMotion ? 0.3f : 1.0f) * f.speed;
    int target = int(float(f.time) * rate * 60.0f + 0.001f);
    int guard = 0;
    while (done < target && guard < 16) {
      step(f.width, f.height);
      guard++;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    Vec2 center{w * 0.5f, h * 0.5f};
    float maxDim = std::max(w, h);

    // 1. Fondo vacío espacial
    Paint bg; bg.color = Color::argb(0xff030107);
    c.rect({0, 0, w, h}, bg);

    // 2. Remanente central (Púlsar ultra-denso con haz rotatorio)
    float bassKick = (1.0f + f.music.bass * 0.5f);
    Paint pulsarGlow = Paint::radial(center, 50.0f * bassKick,
      {{1.0f, 0.35f, 0.0f, std::clamp(0.40f * f.intensity, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    pulsarGlow.blend = Blend::plus;
    c.circle(center, 50.0f * bassKick, pulsarGlow);

    Paint pulsarCore; pulsarCore.blend = Blend::plus;
    pulsarCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * f.intensity, 0.0f, 1.0f)};
    c.circle(center, 5.0f * bassKick, pulsarCore);

    // Haces de emisión del púlsar rotando a gran velocidad
    float beamAngle = t * 4.0f;
    float beamLen = 35.0f * bassKick;
    Paint beamPaint; beamPaint.blend = Blend::plus;
    beamPaint.color = {0.0f, 0.9f, 1.0f, std::clamp(0.6f * f.intensity, 0.0f, 1.0f)};
    beamPaint.strokeWidth = 2.0f;
    Path beams;
    beams.moveTo(center.x - std::cos(beamAngle) * beamLen, center.y - std::sin(beamAngle) * beamLen);
    beams.lineTo(center.x + std::cos(beamAngle) * beamLen, center.y + std::sin(beamAngle) * beamLen);
    c.path(beams, beamPaint);

    // 3. Onda de choque expansiva
    if (shockRadius > 0.0f) {
      float shockAlpha = std::clamp((1.0f - shockRadius / (maxDim * 1.2f)) * f.intensity, 0.0f, 1.0f);
      Paint shockPaint; shockPaint.blend = Blend::plus;
      shockPaint.color = {1.0f, 0.84f, 0.0f, shockAlpha};
      shockPaint.strokeWidth = std::clamp(4.0f * shockAlpha, 1.0f, 4.0f);
      c.circle(center, shockRadius, shockPaint);
    }

    // 4. Renderizar partículas termodinámicas con estelas de velocidad
    const uint32_t thermalPal[5] = {0xffff5722, 0xffffd600, 0xff00e5ff, 0xffff007f, 0xffe040fb};

    for (const auto& p : particles) {
      float speed = std::sqrt(p.vx * p.vx + p.vy * p.vy);
      float trailLen = std::clamp(speed * 1.5f, 2.0f, 24.0f);
      float normVx = (speed > 0.01f) ? (p.vx / speed) : 0.0f;
      float normVy = (speed > 0.01f) ? (p.vy / speed) : 0.0f;

      float px = (done == 0 ? center.x + p.x : p.x);
      float py = (done == 0 ? center.y + p.y : p.y);
      float tailX = px - normVx * trailLen;
      float tailY = py - normVy * trailLen;

      Color base = Color::argb(thermalPal[p.colIdx]);
      // Transición termodinámica hacia el blanco en alta energía
      Color col{
        base.r * (1.0f - p.energy) + 1.0f * p.energy,
        base.g * (1.0f - p.energy) + 1.0f * p.energy,
        base.b * (1.0f - p.energy) + 1.0f * p.energy,
        std::clamp((0.40f + p.energy * 0.60f) * f.intensity, 0.0f, 1.0f)
      };

      Paint partPaint; partPaint.blend = Blend::plus;
      partPaint.color = col;
      partPaint.strokeWidth = std::max(1.0f, p.size);
      partPaint.strokeCap = 1;

      Path pLine; pLine.moveTo(tailX, tailY); pLine.lineTo(px, py);
      c.path(pLine, partPaint);
    }
  }
};

