class Visual final : public Scene {
  float rainTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    rainTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un lloviznar suave y sereno (~0.12f).
    // Con música la lluvia cobra ímpetu al compás de los ritmos y bombos.
    float audioDrive = 0.12f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.35f : 1.0f) * f.speed * audioDrive;
    rainTime += dt * speedMult;
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;

    // Renderiza la simulación transparente de lluvia sobre cristal
    c.material("rain_glass_overlay", {0.0f, 0.0f, w, h}, {
      rainTime,
      smoothEnergy,
      smoothSpark * f.intensity,
      smoothBass
    });
  }
};

shaderSources.rain_glass_overlay:
#version 460 core
#include <flutter/runtime_effect.glsl>

uniform vec2 uSize;
uniform float uTime;
uniform float uEnergy;
uniform float uSpark;
uniform float uBass;

out vec4 fragColor;

vec3 hash33(vec3 p3) {
  p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yxz + 33.33);
  return fract((p3.xxy + p3.yzz) * p3.zyx);
}

// Simulación física multicapa de gotas de lluvia
vec4 getRain(vec2 uv, float t, vec2 aspect) {
  vec2 totalNormal = vec2(0.0);
  float dropMask = 0.0;
  float trailMask = 0.0;
  float rimMask = 0.0;

  // CAPA 1: Gotas grandes deslizándose con física de stutter-slide (adherencia y caída brusca)
  vec2 uv1 = uv * vec2(3.5, 1.2) * aspect;
  vec2 id1 = floor(uv1);
  vec2 f1 = fract(uv1) - 0.5;

  for (int dy = -1; dy <= 1; dy++) {
    for (int dx = -1; dx <= 1; dx++) {
      vec2 neighbor = vec2(float(dx), float(dy));
      vec2 cId = id1 + neighbor;
      vec3 rnd = hash33(vec3(cId, 45.2));

      if (rnd.x < 0.42) {
        float speed = 0.35 + rnd.y * 0.45;
        float fallTime = t * speed + rnd.z * 100.0;

        // Física stutter-slide: escalonamiento por tensión superficial
        float stepPhase = fract(fallTime);
        float dropY = floor(fallTime) + smoothstep(0.70, 0.98, stepPhase);

        vec2 dropCenter = neighbor + vec2((rnd.y - 0.5) * 0.35, fract(dropY) - 0.5);
        vec2 dVec = f1 - dropCenter;

        // Estiramiento aerodinámico por gravedad
        dVec.y *= 0.85;
        float dist = length(dVec);
        float r = 0.12 + 0.08 * rnd.x;

        if (dist < r) {
          float normDist = dist / r;
          float edgeSoft = smoothstep(1.0, 0.70, normDist);
          vec2 norm2D = (dVec / r) * edgeSoft;
          totalNormal += norm2D * 0.75;
          dropMask = max(dropMask, edgeSoft);
          rimMask = max(rimMask, smoothstep(0.65, 0.96, normDist) * edgeSoft);
        }

        // Estela vertical dejada por la gota
        float trailX = dVec.x;
        float trailY = dVec.y;
        if (trailY > 0.0 && trailY < 0.95 && abs(trailX) < r * 0.38) {
          float trailFade = (1.0 - trailY / 0.95);
          float trailWidth = smoothstep(r * 0.38, 0.0, abs(trailX));
          trailMask = max(trailMask, trailWidth * trailFade * 0.45);
          totalNormal.x += trailX * trailWidth * 0.35;
        }
      }
    }
  }

  // CAPA 2: Gotas medianas estáticas y micro-perlas
  vec2 uv2 = uv * vec2(9.0, 6.0) * aspect;
  vec2 id2 = floor(uv2);
  vec2 f2 = fract(uv2) - 0.5;

  for (int dy = -1; dy <= 1; dy++) {
    for (int dx = -1; dx <= 1; dx++) {
      vec2 neighbor = vec2(float(dx), float(dy));
      vec2 cId = id2 + neighbor;
      vec3 rnd = hash33(vec3(cId, 88.9));

      if (rnd.x < 0.65) {
        vec2 dropCenter = neighbor + (rnd.yz - 0.5) * 0.60;
        vec2 dVec = f2 - dropCenter;
        float dist = length(dVec);
        float r = 0.075 + 0.065 * rnd.y;

        if (dist < r) {
          float normDist = dist / r;
          float edgeSoft = smoothstep(1.0, 0.65, normDist);
          vec2 norm2D = (dVec / r) * edgeSoft * 0.55;
          totalNormal += norm2D;
          dropMask = max(dropMask, edgeSoft * 0.85);
          rimMask = max(rimMask, smoothstep(0.60, 0.95, normDist) * edgeSoft * 0.70);
        }
      }
    }
  }

  return vec4(totalNormal, max(dropMask, trailMask), rimMask);
}

void main() {
  vec2 px = FlutterFragCoord().xy;
  vec2 uv = px / uSize;
  vec2 aspect = vec2(uSize.x / max(uSize.y, 1.0), 1.0);

  // Simulación física de capas de lluvia
  vec4 rain = getRain(uv, uTime, aspect);
  vec2 normal = rain.xy;
  float dropMask = rain.z;
  float rimMask = rain.w;

  // Reactividad a graves: ondas de tensión superficial
  if (uBass > 0.03) {
    normal += vec2(sin(uv.y * 70.0 + uTime * 10.0), cos(uv.x * 70.0 + uTime * 10.0)) * (uBass * 0.016);
  }

  // Iluminación cáustica de borde (refracción interna en cristal transparente)
  vec3 causticCol = vec3(0.82, 0.94, 1.00) * (0.65 + uSpark * 0.45);
  vec3 col = causticCol * rimMask;

  // Brillo especular superior del cielo/luz cenital
  vec2 specDir = normalize(vec2(-0.55, -0.80));
  float specDot = max(0.0, dot(normalize(vec3(normal, 0.45)), vec3(specDir, 0.75)));
  float spec = pow(specDot, 20.0) * dropMask;
  col += vec3(1.0, 1.0, 1.0) * spec * (0.85 + uSpark * 0.45);

  // Cuerpo de agua ligeramente cian translúcido en el interior de la gota
  col += vec3(0.35, 0.65, 0.88) * dropMask * 0.35;

  // Destello de relámpago con agudos altos
  if (uSpark > 0.08) {
    col += vec3(0.70, 0.85, 1.00) * (uSpark * 0.40) * dropMask;
  }

  // Alpha transparente: fondo completamente vacío, solo gotas y rastros visibles
  float alpha = clamp(dropMask * 0.28 + rimMask * 0.78 + spec * 0.95, 0.0, 1.0);

  fragColor = vec4(clamp(col, 0.0, 1.0) * alpha, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct PlasmaIon {
    int lineIdx;
    float prog;
    float speed;
    float phase;
    float size;
    int colIdx;
  };

  struct Filing {
    float x, y;
    float angle;
    float len;
    bool isPolar;
  };

  static constexpr int kLines = 48;
  static constexpr int kLinePts = 64;
  static constexpr int kIonCount = 380;
  static constexpr int kFilingCount = 2200;

  // Tubos de flujo magnético precalculados por fotograma
  Vec2 linePts[kLines][kLinePts];

  std::vector<PlasmaIon> ions;
  std::vector<Filing> filings;

  float simTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

  float targetPolarity = 1.0f;
  float polarityAngle = 0.0f;
  float polarityVel = 0.0f;
  float lastInvertTime = -10.0f;

  float shockRadius1 = 0.0f;
  float shockRadius2 = 0.0f;

  static Vec2 evalFieldDir(float x, float y, float mx, float my) {
    const float soft2 = 0.014f;
    float bx = 0.0f, by = 0.0f;

    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? -0.28f : 0.28f;
      float sign = (p == 0) ? 1.0f : -1.0f;
      float dx = x - px;
      float dy = y;
      float r2 = dx * dx + dy * dy + soft2;
      float invR25 = 1.0f / (r2 * std::sqrt(r2));
      float invR35 = invR25 / r2;

      float mDotD = sign * (mx * dx + my * dy);
      float dVdx = sign * mx * invR25 - 3.0f * dx * mDotD * invR35;
      float dVdy = sign * my * invR25 - 3.0f * dy * mDotD * invR35;

      bx -= dVdx;
      by -= dVdy;
    }

    float len = std::sqrt(bx * bx + by * by);
    if (len < 1e-5f) return Vec2{0.0f, 1.0f};
    return Vec2{bx / len, by / len};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    simTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    targetPolarity = 1.0f;
    polarityAngle = 0.0f;
    polarityVel = 0.0f;
    lastInvertTime = -10.0f;
    shockRadius1 = 0.0f;
    shockRadius2 = 0.0f;

    ions.clear();
    ions.reserve(kIonCount);
    for (int i = 0; i < kIonCount; i++) {
      ions.push_back({
        i % kLines,
        rng.unit(),
        0.35f + rng.unit() * 0.55f,
        rng.unit() * 6.2831853f,
        1.2f + rng.unit() * 2.2f,
        int(rng.unit() * 3.999f)
      });
    }

    filings.clear();
    filings.reserve(kFilingCount);
    for (int i = 0; i < kFilingCount; i++) {
      Filing f;
      if (i < 1500) {
        // 70% concentrado cerca de los dos polos
        float poleX = (i % 2 == 0) ? -0.28f : 0.28f;
        float r = std::pow(rng.unit(), 1.8f) * 0.42f + 0.025f;
        float th = rng.unit() * 6.2831853f;
        f.x = poleX + std::cos(th) * r;
        f.y = std::sin(th) * r * 0.85f;
        f.len = 0.008f + rng.unit() * 0.006f;
        f.isPolar = true;
      } else {
        // 30% ambiente
        f.x = (rng.unit() - 0.5f) * 1.15f;
        f.y = (rng.unit() - 0.5f) * 0.95f;
        f.len = 0.006f + rng.unit() * 0.005f;
        f.isPolar = false;
      }
      Vec2 b = evalFieldDir(f.x, f.y, 1.0f, 0.0f);
      f.angle = std::atan2(b.y, b.x);
      filings.push_back(f);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un flujo magnético laminar lento (~0.10f).
    // Con música acelera el flujo de iones Lorentz y desata arcos e inversiones de dipolo.
    float audioDrive = 0.10f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.3f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Inversión física del dipolo ante bombos rítmicos marcados con música activa
    if (f.music.active && !f.reducedMotion && f.music.bass > 0.80f && (simTime - lastInvertTime > 1.8f)) {
      lastInvertTime = simTime;
      targetPolarity *= -1.0f;
      shockRadius1 = 15.0f;
      shockRadius2 = 15.0f;
    }

    // Ondas de choque de inducción
    if (shockRadius1 > 0.0f) {
      shockRadius1 += dt * 320.0f;
      if (shockRadius1 > 450.0f) shockRadius1 = 0.0f;
    }
    if (shockRadius2 > 0.0f) {
      shockRadius2 += dt * 320.0f;
      if (shockRadius2 > 450.0f) shockRadius2 = 0.0f;
    }

    // Muelle físico con amortiguamiento crítico para la orientación del dipolo
    float targetAngle = (targetPolarity > 0.0f) ? 0.0f : 3.14159265f;
    float omega = 9.5f;
    float diffAngle = targetAngle - polarityAngle;
    polarityVel += (diffAngle * omega * omega - 2.0f * omega * 0.78f * polarityVel) * dt;
    polarityAngle += polarityVel * dt;

    float mx = std::cos(polarityAngle);
    float my = std::sin(polarityAngle);

    // Integración de los 48 tubos de flujo
    float stepDt = 0.0022f;
    for (int l = 0; l < kLines; l++) {
      float ang = (float(l) / float(kLines)) * 6.2831853f;
      float startPole = (l % 2 == 0) ? -0.28f : 0.28f;
      float x = startPole + std::cos(ang) * 0.038f;
      float y = std::sin(ang) * 0.038f;
      float dirSign = (l % 2 == 0) ? 1.0f : -1.0f;

      for (int pt = 0; pt < kLinePts; pt++) {
        linePts[l][pt] = Vec2{x, y};
        for (int sub = 0; sub < 4; sub++) {
          Vec2 b = evalFieldDir(x, y, mx, my);
          x += b.x * stepDt * dirSign;
          y += b.y * stepDt * dirSign;
        }
      }
    }

    // Actualización de iones de plasma (movimiento de Lorentz a lo largo de las líneas)
    float ionSpeedFactor = (1.0f + smoothEnergy * 0.85f);
    for (auto& ion : ions) {
      ion.prog += dt * ion.speed * 0.45f * ionSpeedFactor;
      if (ion.prog >= 1.0f) {
        ion.prog = std::fmod(ion.prog, 1.0f);
      }
    }

    // Alineación física de limaduras de hierro con amortiguamiento
    float alignRate = std::min(1.0f, dt * 14.0f);
    for (auto& fil : filings) {
      Vec2 b = evalFieldDir(fil.x, fil.y, mx, my);
      float targetA = std::atan2(b.y, b.x);
      float deltaA = targetA - fil.angle;
      while (deltaA > 3.14159265f) deltaA -= 6.2831853f;
      while (deltaA < -3.14159265f) deltaA += 6.2831853f;
      fil.angle += deltaA * alignRate;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float boost = std::clamp((0.85f + smoothEnergy * 0.40f) * f.intensity, 0.0f, 1.0f);

    float mx = std::cos(polarityAngle);

    // 1. Cámara oscura de laboratorio electromagnético #080b12
    Paint bg = Paint::radial(center, minDim * 0.85f,
      {Color::argb(0xff101726), Color::argb(0xff080b12), Color::argb(0xff030407)},
      {0.0f, 0.55f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Reflejo difuso central
    Paint chamberGlow = Paint::radial(center, minDim * 0.45f,
      {{0.0f, 0.94f, 1.0f, std::clamp(0.12f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    chamberGlow.blend = Blend::plus;
    c.circle(center, minDim * 0.45f, chamberGlow);

    // Ondas de choque de inducción expansivas
    if (shockRadius1 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius1 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.0f, 0.94f, 1.0f, alpha};
      c.circle({center.x - 0.28f * minDim, center.y}, shockRadius1, shk);
    }
    if (shockRadius2 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius2 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.62f, 0.31f, 0.87f, alpha};
      c.circle({center.x + 0.28f * minDim, center.y}, shockRadius2, shk);
    }

    // 2. Campo de limaduras de hierro orientadas (Ferrofluido que vibra con el audio)
    Path filingsPath;
    float filingLengthMult = 0.5f * (1.0f + smoothBass * 0.45f);

    for (const auto& fil : filings) {
      float sx = center.x + fil.x * minDim;
      float sy = center.y + fil.y * minDim;
      float flen = fil.len * minDim * filingLengthMult;
      float dx = std::cos(fil.angle) * flen;
      float dy = std::sin(fil.angle) * flen;
      filingsPath.moveTo(sx - dx, sy - dy);
      filingsPath.lineTo(sx + dx, sy + dy);
    }
    Paint filPaint; filPaint.blend = Blend::plus;
    filPaint.color = {0.45f, 0.65f, 0.95f, std::clamp(0.40f * boost, 0.0f, 1.0f)};
    filPaint.strokeWidth = 1.1f;
    c.path(filingsPath, filPaint);

    // 3. Tubos de flujo magnético en arco (Cian -> Violeta -> Azul)
    Path linesCyan, linesViolet;

    for (int l = 0; l < kLines; l++) {
      Path& curPath = (l % 2 == 0) ? linesCyan : linesViolet;
      bool first = true;
      for (int pt = 0; pt < kLinePts; pt++) {
        float sx = center.x + linePts[l][pt].x * minDim;
        float sy = center.y + linePts[l][pt].y * minDim;
        if (first) { curPath.moveTo(sx, sy); first = false; }
        else curPath.lineTo(sx, sy);
      }
    }

    // Halo ancho de los tubos de flujo
    Paint lpGlow; lpGlow.blend = Blend::plus;
    lpGlow.strokeWidth = 3.5f;
    lpGlow.color = {0.0f, 0.94f, 1.0f, std::clamp(0.22f * boost, 0.0f, 1.0f)};
    c.path(linesCyan, lpGlow);
    lpGlow.color = {0.62f, 0.31f, 0.87f, std::clamp(0.22f * boost, 0.0f, 1.0f)};
    c.path(linesViolet, lpGlow);

    // Filamentos brillantes de flujo
    Paint lpCore; lpCore.blend = Blend::plus;
    lpCore.strokeWidth = 1.3f;
    lpCore.color = {0.50f, 0.95f, 1.0f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    c.path(linesCyan, lpCore);
    lpCore.color = {0.85f, 0.50f, 1.0f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    c.path(linesViolet, lpCore);

    // 4. Plasma de Lorentz: iones bioluminiscentes en espirales ciclotrón
    const Color ionCols[4] = {
      {1.0f, 1.0f, 1.0f, 1.0f},
      {0.0f, 0.95f, 1.0f, 1.0f},
      {0.75f, 0.35f, 1.0f, 1.0f},
      {1.0f, 0.85f, 0.20f, 1.0f}
    };

    for (const auto& ion : ions) {
      int lIdx = ion.lineIdx;
      float fIdx = ion.prog * float(kLinePts - 1);
      int p0 = std::clamp(int(fIdx), 0, kLinePts - 2);
      int p1 = p0 + 1;
      float frac = fIdx - float(p0);

      Vec2 pt0 = linePts[lIdx][p0];
      Vec2 pt1 = linePts[lIdx][p1];
      float basePx = center.x + (pt0.x + (pt1.x - pt0.x) * frac) * minDim;
      float basePy = center.y + (pt0.y + (pt1.y - pt0.y) * frac) * minDim;

      // Espiral de ciclotrón transversal a la línea de campo
      float helixAngle = ion.prog * 35.0f + ion.phase + simTime * 6.0f;
      float helixRad = (1.5f + std::sin(ion.prog * 3.14159f) * 4.5f);
      float ipx = basePx + std::cos(helixAngle) * helixRad;
      float ipy = basePy + std::sin(helixAngle) * helixRad;

      Color ic = ionCols[ion.colIdx];
      Paint ionPaint; ionPaint.blend = Blend::plus;
      ionPaint.color = {ic.r, ic.g, ic.b, std::clamp(0.85f * boost, 0.0f, 1.0f)};
      c.circle({ipx, ipy}, ion.size * (1.0f + smoothEnergy * 0.4f), ionPaint);
    }

    // 5. Arcos eléctricos Tesla de alta tensión ante transients y chispas
    if (smoothSpark > 0.18f || smoothBass > 0.75f) {
      float p1x = center.x - 0.28f * minDim;
      float p2x = center.x + 0.28f * minDim;
      float sparkInt = std::max(smoothSpark, (smoothBass - 0.65f) * 2.0f);

      Path lightning;
      lightning.moveTo(p1x, center.y);
      const int arcSteps = 16;
      for (int s = 1; s < arcSteps; s++) {
        float u = float(s) / float(arcSteps);
        float lx = p1x + (p2x - p1x) * u;
        float envelope = std::sin(u * 3.14159265f);
        float jitterY = std::sin(float(s) * 17.3f + simTime * 120.0f) * 28.0f * envelope * sparkInt;
        float jitterX = std::cos(float(s) * 11.7f + simTime * 95.0f) * 8.0f * envelope * sparkInt;
        lightning.lineTo(lx + jitterX, center.y + jitterY);
      }
      lightning.lineTo(p2x, center.y);

      // Resplandor del rayo
      Paint arcGlow; arcGlow.blend = Blend::plus;
      arcGlow.strokeWidth = 5.5f;
      arcGlow.color = {0.0f, 0.85f, 1.0f, std::clamp(0.60f * sparkInt * boost, 0.0f, 1.0f)};
      c.path(lightning, arcGlow);

      // Núcleo blanco del rayo
      Paint arcCore; arcCore.blend = Blend::plus;
      arcCore.strokeWidth = 2.0f;
      arcCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * sparkInt * boost, 0.0f, 1.0f)};
      c.path(lightning, arcCore);
    }

    // 6. Dos Electroimanes Industriales con bobinas de cobre incandescentes
    for (int p = 0; p < 2; p++) {
      float poleSign = (p == 0) ? -1.0f : 1.0f;
      float px = center.x + poleSign * 0.28f * minDim;
      float py = center.y;
      float cylW = minDim * 0.088f;
      float cylH = minDim * 0.155f;

      bool isNorth = (poleSign * mx >= 0.0f);
      Color poleTint = isNorth ? Color{0.0f, 0.94f, 1.0f, 1.0f} : Color{0.75f, 0.25f, 1.0f, 1.0f};

      // Resplandor de inducción del polo
      float coreGlowR = cylW * (1.2f + smoothEnergy * 0.5f + smoothBass * 0.4f);
      Paint coreGlow = Paint::radial({px, py}, coreGlowR,
        {{1.0f, 1.0f, 1.0f, std::clamp(0.75f * boost, 0.0f, 1.0f)},
         {poleTint.r, poleTint.g, poleTint.b, std::clamp(0.40f * boost, 0.0f, 1.0f)},
         {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
      coreGlow.blend = Blend::plus;
      c.circle({px, py}, coreGlowR, coreGlow);

      // Cuerpo cilíndrico de acero de alta densidad
      Paint cylBody; cylBody.color = Color::argb(0xff181d26);
      c.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH}, cylBody);

      Paint cylBorder; cylBorder.color = Color::argb(0xff3c4657); cylBorder.strokeWidth = 1.8f;
      Path cylBox; cylBox.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH});
      c.path(cylBox, cylBorder);

      // 5 Vueltas de bobina de cobre incandescente (#b87333 / oro fundido)
      Path copperCoils;
      for (int turn = 0; turn < 5; turn++) {
        float ty = py - cylH * 0.35f + (float(turn) / 4.0f) * (cylH * 0.70f);
        copperCoils.moveTo(px - cylW * 0.58f, ty - 3.5f);
        copperCoils.cubicTo(
          px - cylW * 0.2f, ty + 5.0f,
          px + cylW * 0.2f, ty - 5.0f,
          px + cylW * 0.58f, ty + 3.5f
        );
      }
      Paint coilPaint;
      coilPaint.color = {0.92f, 0.55f, 0.20f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
      coilPaint.strokeWidth = 3.6f;
      c.path(copperCoils, coilPaint);

      // Brillo especular sobre el cobre
      Paint coilSpec; coilSpec.blend = Blend::plus;
      coilSpec.color = {1.0f, 0.90f, 0.70f, std::clamp(0.60f * boost, 0.0f, 1.0f)};
      coilSpec.strokeWidth = 1.4f;
      c.path(copperCoils, coilSpec);

      // Núcleo blanco del emisor de campo
      Paint emitterCore; emitterCore.blend = Blend::plus;
      emitterCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.92f * boost, 0.0f, 1.0f)};
      c.circle({px, py}, cylW * 0.22f, emitterCore);
    }
  }
};

class Visual final : public Scene {
  struct PlasmaIon {
    int lineIdx;
    float prog;
    float speed;
    float phase;
    float size;
    int colIdx;
  };

  struct Filing {
    float x, y;
    float angle;
    float len;
    bool isPolar;
  };

  static constexpr int kLines = 48;
  static constexpr int kLinePts = 64;
  static constexpr int kIonCount = 380;
  static constexpr int kFilingCount = 2200;

  // Tubos de flujo magnético precalculados por fotograma
  Vec2 linePts[kLines][kLinePts];

  std::vector<PlasmaIon> ions;
  std::vector<Filing> filings;

  float simTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

  float targetPolarity = 1.0f;
  float polarityAngle = 0.0f;
  float polarityVel = 0.0f;
  float lastInvertTime = -10.0f;

  float shockRadius1 = 0.0f;
  float shockRadius2 = 0.0f;

  static Vec2 evalFieldDir(float x, float y, float mx, float my) {
    const float soft2 = 0.014f;
    float bx = 0.0f, by = 0.0f;

    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? -0.28f : 0.28f;
      float sign = (p == 0) ? 1.0f : -1.0f;
      float dx = x - px;
      float dy = y;
      float r2 = dx * dx + dy * dy + soft2;
      float invR25 = 1.0f / (r2 * std::sqrt(r2));
      float invR35 = invR25 / r2;

      float mDotD = sign * (mx * dx + my * dy);
      float dVdx = sign * mx * invR25 - 3.0f * dx * mDotD * invR35;
      float dVdy = sign * my * invR25 - 3.0f * dy * mDotD * invR35;

      bx -= dVdx;
      by -= dVdy;
    }

    float len = std::sqrt(bx * bx + by * by);
    if (len < 1e-5f) return Vec2{0.0f, 1.0f};
    return Vec2{bx / len, by / len};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    simTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;
    targetPolarity = 1.0f;
    polarityAngle = 0.0f;
    polarityVel = 0.0f;
    lastInvertTime = -10.0f;
    shockRadius1 = 0.0f;
    shockRadius2 = 0.0f;

    ions.clear();
    ions.reserve(kIonCount);
    for (int i = 0; i < kIonCount; i++) {
      ions.push_back({
        i % kLines,
        rng.unit(),
        0.35f + rng.unit() * 0.55f,
        rng.unit() * 6.2831853f,
        1.2f + rng.unit() * 2.2f,
        int(rng.unit() * 3.999f)
      });
    }

    filings.clear();
    filings.reserve(kFilingCount);
    for (int i = 0; i < kFilingCount; i++) {
      Filing f;
      if (i < 1500) {
        // 70% concentrado cerca de los dos polos
        float poleX = (i % 2 == 0) ? -0.28f : 0.28f;
        float r = std::pow(rng.unit(), 1.8f) * 0.42f + 0.025f;
        float th = rng.unit() * 6.2831853f;
        f.x = poleX + std::cos(th) * r;
        f.y = std::sin(th) * r * 0.85f;
        f.len = 0.012f + (1.0f - std::min(r / 0.42f, 1.0f)) * 0.022f;
        f.isPolar = true;
      } else {
        // 30% distribuido por el espacio
        f.x = (rng.unit() - 0.5f) * 1.55f;
        f.y = (rng.unit() - 0.5f) * 1.55f;
        f.len = 0.010f + rng.unit() * 0.014f;
        f.isPolar = false;
      }
      f.angle = rng.unit() * 3.14159265f;
      filings.push_back(f);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 6.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 7.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un flujo de Lorentz suave (~0.10f). Con música acelera.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.3f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Inversión de polaridad en caídas de bajos con música activa
    if (f.music.active && f.music.bass > 0.78f && (simTime - lastInvertTime >= 1.6f)) {
      lastInvertTime = simTime;
      targetPolarity *= -1.0f;
      shockRadius1 = 12.0f;
      shockRadius2 = 12.0f;
    }

    if (shockRadius1 > 0.0f) {
      shockRadius1 += dt * 420.0f;
      if (shockRadius1 > 450.0f) shockRadius1 = 0.0f;
    }
    if (shockRadius2 > 0.0f) {
      shockRadius2 += dt * 420.0f;
      if (shockRadius2 > 450.0f) shockRadius2 = 0.0f;
    }

    float targetAngle = (targetPolarity > 0.0f) ? 0.0f : 3.14159265f;
    float angleDiff = targetAngle - polarityAngle;
    while (angleDiff > 3.14159265f) angleDiff -= 6.2831853f;
    while (angleDiff < -3.14159265f) angleDiff += 6.2831853f;
    polarityVel += (angleDiff * 38.0f - polarityVel * 9.5f) * dt;
    polarityAngle += polarityVel * dt;

    float mx = std::cos(polarityAngle);
    float my = std::sin(polarityAngle);

    // Recomputar los 48 tubos de flujo
    for (int l = 0; l < kLines; l++) {
      float side = (l < kLines / 2) ? 1.0f : -1.0f;
      int idx = l % (kLines / 2);
      float frac = float(idx) / float(kLines / 2 - 1);
      float emitterAngle = (frac - 0.5f) * 2.5f;

      float p1x = -0.28f + std::cos(emitterAngle) * 0.038f;
      float p1y = side * (0.015f + std::sin(std::abs(emitterAngle)) * 0.038f);
      float p2x = 0.28f - std::cos(emitterAngle) * 0.038f;
      float p2y = side * (0.015f + std::sin(std::abs(emitterAngle)) * 0.038f);

      float apexDist = 0.16f + std::pow(frac, 1.45f) * 0.72f * (1.0f + smoothBass * 0.40f);
      float apexY = side * apexDist;
      float apexX = (emitterAngle * 0.045f) + std::sin(simTime * 1.8f + float(l) * 0.2f) * (0.012f + smoothEnergy * 0.02f);

      for (int pt = 0; pt < kLinePts; pt++) {
        float u = float(pt) / float(kLinePts - 1);
        float omt = 1.0f - u;
        float bx = omt * omt * p1x + 2.0f * omt * u * apexX + u * u * p2x;
        float by = omt * omt * p1y + 2.0f * omt * u * apexY + u * u * p2y;

        float wav = std::sin(u * 14.0f - simTime * (4.0f + smoothEnergy * 5.0f) + float(l) * 0.35f);
        float wavAmp = (0.003f + smoothSpark * 0.008f) * std::sin(u * 3.14159265f);
        by += wav * wavAmp * side;

        linePts[l][pt] = Vec2{bx, by};
      }
    }

    // Actualizar iones de Lorentz
    for (auto& ion : ions) {
      ion.prog += dt * ion.speed * (0.75f + smoothEnergy * 0.85f);
      if (ion.prog >= 1.0f) ion.prog -= 1.0f;
      ion.phase += dt * (12.0f + smoothSpark * 18.0f);
    }

    // Orientar las 2200 limaduras de hierro
    float alignRate = std::clamp(dt * 18.0f, 0.0f, 1.0f);
    for (auto& fil : filings) {
      Vec2 b = evalFieldDir(fil.x, fil.y, mx, my);
      float targetA = std::atan2(b.y, b.x);
      float deltaA = targetA - fil.angle;
      while (deltaA > 3.14159265f) deltaA -= 6.2831853f;
      while (deltaA < -3.14159265f) deltaA += 6.2831853f;
      fil.angle += deltaA * alignRate;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float boost = std::clamp((0.85f + smoothEnergy * 0.40f) * f.intensity, 0.0f, 1.0f);

    // Sin fondo opaco: lienzo 100% transparente

    // 1. Reflejo difuso central aditivo
    Paint chamberGlow = Paint::radial(center, minDim * 0.45f,
      {{0.0f, 0.94f, 1.0f, std::clamp(0.12f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    chamberGlow.blend = Blend::plus;
    c.circle(center, minDim * 0.45f, chamberGlow);

    // Ondas de choque de inducción expansivas
    if (shockRadius1 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius1 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.0f, 0.94f, 1.0f, alpha};
      c.circle({center.x - 0.28f * minDim, center.y}, shockRadius1, shk);
    }
    if (shockRadius2 > 0.0f) {
      float alpha = std::clamp((1.0f - shockRadius2 / 450.0f) * 0.40f * boost, 0.0f, 1.0f);
      Paint shk; shk.blend = Blend::plus; shk.strokeWidth = 2.0f;
      shk.color = {0.62f, 0.31f, 0.87f, alpha};
      c.circle({center.x + 0.28f * minDim, center.y}, shockRadius2, shk);
    }

    // 2. Campo de limaduras de hierro orientadas (Ferrofluido que vibra con el audio)
    Path filingsPath;
    float filingLengthMult = 0.5f * (1.0f + smoothBass * 0.45f);

    for (const auto& fil : filings) {
      float sx = center.x + fil.x * minDim;
      float sy = center.y + fil.y * minDim;
      float flen = fil.len * minDim * filingLengthMult;
      float dx = std::cos(fil.angle) * flen;
      float dy = std::sin(fil.angle) * flen;
      filingsPath.moveTo(sx - dx, sy - dy);
      filingsPath.lineTo(sx + dx, sy + dy);
    }
    Paint filPaint; filPaint.blend = Blend::plus;
    filPaint.color = {0.45f, 0.65f, 0.95f, std::clamp(0.40f * boost, 0.0f, 1.0f)};
    filPaint.strokeWidth = 1.1f;
    c.path(filingsPath, filPaint);

    // 3. Tubos de flujo magnético en arco (Cian -> Violeta -> Azul)
    Path linesCyan, linesViolet;

    for (int l = 0; l < kLines; l++) {
      Path& curPath = (l % 2 == 0) ? linesCyan : linesViolet;
      bool first = true;
      for (int pt = 0; pt < kLinePts; pt++) {
        float sx = center.x + linePts[l][pt].x * minDim;
        float sy = center.y + linePts[l][pt].y * minDim;
        if (first) { curPath.moveTo(sx, sy); first = false; }
        else curPath.lineTo(sx, sy);
      }
    }

    // Halo ancho de los tubos de flujo
    Paint lpGlow; lpGlow.blend = Blend::plus;
    lpGlow.strokeWidth = 3.5f;
    lpGlow.color = {0.0f, 0.94f, 1.0f, std::clamp(0.22f * boost, 0.0f, 1.0f)};
    c.path(linesCyan, lpGlow);
    lpGlow.color = {0.62f, 0.31f, 0.87f, std::clamp(0.22f * boost, 0.0f, 1.0f)};
    c.path(linesViolet, lpGlow);

    // Filamentos brillantes de flujo
    Paint lpCore; lpCore.blend = Blend::plus;
    lpCore.strokeWidth = 1.3f;
    lpCore.color = {0.50f, 0.95f, 1.0f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    c.path(linesCyan, lpCore);
    lpCore.color = {0.85f, 0.50f, 1.0f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    c.path(linesViolet, lpCore);

    // 4. Plasma de Lorentz: iones bioluminiscentes en espirales ciclotrón
    const Color ionCols[4] = {
      {1.0f, 1.0f, 1.0f, 1.0f},
      {0.0f, 0.95f, 1.0f, 1.0f},
      {0.75f, 0.35f, 1.0f, 1.0f},
      {1.0f, 0.85f, 0.20f, 1.0f}
    };

    std::vector<Vec2> ionPoints[4];
    for (const auto& ion : ions) {
      int l = ion.lineIdx;
      float pNorm = ion.prog * float(kLinePts - 1);
      int idx0 = std::clamp(int(pNorm), 0, kLinePts - 2);
      float frac = pNorm - float(idx0);

      Vec2 p0 = linePts[l][idx0];
      Vec2 p1 = linePts[l][idx0 + 1];
      float bx = p0.x + (p1.x - p0.x) * frac;
      float by = p0.y + (p1.y - p0.y) * frac;

      float gyroR = (0.005f + smoothSpark * 0.012f) * (0.8f + 0.4f * std::sin(ion.phase));
      float px = center.x + (bx + std::cos(ion.phase) * gyroR) * minDim;
      float py = center.y + (by + std::sin(ion.phase) * gyroR) * minDim;

      ionPoints[ion.colIdx].push_back({px, py});
    }

    for (int cIdx = 0; cIdx < 4; cIdx++) {
      if (!ionPoints[cIdx].empty()) {
        Paint ip; ip.blend = Blend::plus;
        Color baseCol = ionCols[cIdx];
        ip.color = {baseCol.r, baseCol.g, baseCol.b, std::clamp(0.85f * boost, 0.0f, 1.0f)};
        c.points(ionPoints[cIdx], 1.8f + smoothSpark * 1.6f, ip);
      }
    }

    // 5. Arcos eléctricos Tesla bifurcados entre los polos
    if (f.music.active && smoothSpark > 0.35f) {
      Path arcPath;
      float pole1X = center.x - 0.28f * minDim;
      float pole2X = center.x + 0.28f * minDim;
      float baseY = center.y;

      arcPath.moveTo(pole1X, baseY);
      const int kArcSteps = 12;
      for (int step = 1; step < kArcSteps; step++) {
        float u = float(step) / float(kArcSteps);
        float ax = pole1X + (pole2X - pole1X) * u;
        float sag = std::sin(u * 3.14159265f) * (std::sin(simTime * 35.0f + float(step)) * 24.0f * smoothSpark);
        float ay = baseY + sag;
        arcPath.lineTo(ax, ay);
      }
      arcPath.lineTo(pole2X, baseY);

      Paint arcPaint; arcPaint.blend = Blend::plus;
      arcPaint.strokeWidth = 2.2f;
      arcPaint.color = {1.0f, 1.0f, 1.0f, std::clamp(smoothSpark * boost, 0.0f, 1.0f)};
      c.path(arcPath, arcPaint);
    }

    // 6. Polos magnéticos translúcidos con bobinas de cobre
    for (int p = 0; p < 2; p++) {
      float px = (p == 0) ? (center.x - 0.28f * minDim) : (center.x + 0.28f * minDim);
      float py = center.y;
      Color poleColor = (p == 0) ? Color{0.0f, 0.95f, 1.0f, 1.0f} : Color{0.75f, 0.35f, 1.0f, 1.0f};

      // Resplandor del polo
      Paint poleGlow = Paint::radial({px, py}, minDim * 0.16f,
        {{poleColor.r, poleColor.g, poleColor.b, std::clamp(0.65f * boost, 0.0f, 1.0f)}, {0, 0, 0, 0}},
        {0.0f, 1.0f});
      poleGlow.blend = Blend::plus;
      c.circle({px, py}, minDim * 0.16f, poleGlow);

      // Cilindro del electroimán
      float cylW = minDim * 0.075f;
      float cylH = minDim * 0.14f;

      Paint cylBorder; cylBorder.color = {0.35f, 0.45f, 0.55f, 0.85f}; cylBorder.strokeWidth = 1.8f;
      Path cylBox; cylBox.rect({px - cylW * 0.5f, py - cylH * 0.5f, cylW, cylH});
      c.path(cylBox, cylBorder);

      // Vueltas de bobina de cobre incandescente
      Path copperCoils;
      for (int turn = 0; turn < 5; turn++) {
        float ty = py - cylH * 0.35f + (float(turn) / 4.0f) * (cylH * 0.70f);
        copperCoils.moveTo(px - cylW * 0.58f, ty - 3.5f);
        copperCoils.cubicTo(
          px - cylW * 0.2f, ty + 5.0f,
          px + cylW * 0.2f, ty - 5.0f,
          px + cylW * 0.58f, ty + 3.5f
        );
      }
      Paint coilPaint;
      coilPaint.color = {0.92f, 0.55f, 0.20f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
      coilPaint.strokeWidth = 3.6f;
      c.path(copperCoils, coilPaint);

      // Brillo especular sobre el cobre
      Paint coilSpec; coilSpec.blend = Blend::plus;
      coilSpec.color = {1.0f, 0.90f, 0.70f, std::clamp(0.60f * boost, 0.0f, 1.0f)};
      coilSpec.strokeWidth = 1.4f;
      c.path(copperCoils, coilSpec);

      // Núcleo blanco del emisor de campo
      Paint emitterCore; emitterCore.blend = Blend::plus;
      emitterCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.92f * boost, 0.0f, 1.0f)};
      c.circle({px, py}, cylW * 0.22f, emitterCore);
    }
  }
};

visuals.shaderSource:
vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.3;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.44;

  float r = length(p);
  float eventHorizon = 0.26 + 0.05 * bass;

  // Gravitational deflection / Einstein ring lensing
  vec2 lensP = p;
  if (r > eventHorizon) {
    float defl = (eventHorizon * eventHorizon) / (r * r + 0.001);
    lensP = p * (1.0 - defl * 0.42);
  }

  // Accretion disk coordinate with tilt and logarithmic spiral
  vec2 diskP = lensP;
  diskP.y *= 2.35; // 3D orbital inclination tilt
  diskP = rotate2D(diskP, 0.38);

  float diskR = length(diskP);
  // Analytical polar angle
  float diskAngle = atan(diskP.y / (diskP.x + 0.00001)) + (diskP.x < 0.0 ? 3.14159 : 0.0);

  // Swirling plasma arms in relativistic accretion disk
  float spiral = diskAngle * 2.0 - log(diskR + 0.001) * 3.4 - t * (2.2 + 1.4 * flow + 1.8 * energy);
  float arm1 = sin(spiral) * 0.5 + 0.5;
  float arm2 = sin(spiral * 2.0 + 1.3) * 0.5 + 0.5;
  float arms = arm1 * 0.7 + arm2 * 0.3;

  // Accretion disk radial bounds
  float diskMask = smoothstep(eventHorizon * 0.88, eventHorizon * 1.32, diskR) *
                   smoothstep(1.65, eventHorizon * 1.5, diskR);

  // Doppler boosting: approaching plasma orbital side is brighter and hotter
  float doppler = 1.0 - clamp(diskP.x * 0.65, -0.65, 0.65);

  // Photon ring radiance directly surrounding event horizon boundary
  float photonDist = abs(r - eventHorizon);
  float photonRing = (0.012 + 0.025 * bass) / (photonDist * photonDist + 0.0028);

  // Color temperature ramp: from fiery volcanic orange to burning electric cyan
  vec3 hotOrange = vec3(1.0, 0.45, 0.12);
  vec3 electricCyan = vec3(0.25, 0.85, 1.0);
  vec3 pureWhite = vec3(1.0, 0.98, 0.92);

  vec3 diskColor = mix(hotOrange, electricCyan, arms * 0.5 + energy * 0.45);
  diskColor = mix(diskColor, pureWhite, pow(arms, 3.0) * (0.45 + spark * 0.8));

  vec3 col = diskColor * arms * diskMask * doppler * (1.6 + bass * 0.85);
  col += vec3(0.28, 0.72, 1.0) * photonRing * (0.85 + energy * 0.65);

  // Background starfield distorted by gravity
  vec2 starGrid = floor(lensP * 28.0);
  float starHash = hash21(starGrid);
  if (starHash > 0.962) {
    if (r > eventHorizon * 1.15) {
      vec2 starFrac = fract(lensP * 28.0) - 0.5;
      float starDist = length(starFrac);
      float starTwinkle = 0.5 + 0.5 * sin(t * 3.0 + starHash * 30.0);
      float starBright = (0.018 * starTwinkle + 0.028 * spark) / (starDist * starDist * 60.0 + 0.05);
      col += vec3(0.85, 0.92, 1.0) * starBright;
    }
  }

  // Black hole pitch black core shadow
  float shadow = smoothstep(eventHorizon * 0.85, eventHorizon * 1.05, r);
  col *= shadow;

  // Relativistic polar jet radiance
  float jetY = abs(p.y);
  float jetX = abs(p.x);
  float jet = exp(-jetX * 36.0) * smoothstep(0.18, 1.25, jetY) * (0.15 + 0.85 * bass);
  col += electricCyan * jet * 0.55;

  // Cinematic tone mapping and soft vignette
  col = col / (col + vec3(0.92));
  float vignette = 1.0 - smoothstep(0.55, 1.45, length(p));
  col *= vignette;

  return vec4(clamp(col * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.3;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.44;

  float r = length(p);
  float eventHorizon = 0.26 + 0.05 * bass;

  // Gravitational deflection / Einstein ring lensing
  vec2 lensP = p;
  if (r > eventHorizon) {
    float defl = (eventHorizon * eventHorizon) / (r * r + 0.001);
    lensP = p * (1.0 - defl * 0.42);
  }

  // Accretion disk coordinate with tilt and logarithmic spiral
  vec2 diskP = lensP;
  diskP.y *= 2.35; // 3D orbital inclination tilt
  diskP = rotate2D(diskP, 0.38);

  float diskR = length(diskP);
  // Analytical polar angle
  float diskAngle = atan(diskP.y / (diskP.x + 0.00001)) + (diskP.x < 0.0 ? 3.14159 : 0.0);

  // Swirling plasma arms in relativistic accretion disk
  float spiral = diskAngle * 2.0 - log(diskR + 0.001) * 3.4 - t * (2.2 + 1.4 * flow + 1.8 * energy);
  float arm1 = sin(spiral) * 0.5 + 0.5;
  float arm2 = sin(spiral * 2.0 + 1.3) * 0.5 + 0.5;
  float arms = arm1 * 0.7 + arm2 * 0.3;

  // Accretion disk radial bounds
  float diskMask = smoothstep(eventHorizon * 0.88, eventHorizon * 1.32, diskR) *
                   smoothstep(1.65, eventHorizon * 1.5, diskR);

  // Doppler boosting: approaching plasma orbital side is brighter and hotter
  float doppler = 1.0 - clamp(diskP.x * 0.65, -0.65, 0.65);

  // Photon ring radiance directly surrounding event horizon boundary
  float photonDist = abs(r - eventHorizon);
  float photonRing = (0.012 + 0.025 * bass) / (photonDist * photonDist + 0.0028);

  // Color temperature ramp: from fiery volcanic orange to burning electric cyan
  vec3 hotOrange = vec3(1.0, 0.45, 0.12);
  vec3 electricCyan = vec3(0.25, 0.85, 1.0);
  vec3 pureWhite = vec3(1.0, 0.98, 0.92);

  vec3 diskColor = mix(hotOrange, electricCyan, arms * 0.5 + energy * 0.45);
  diskColor = mix(diskColor, pureWhite, pow(arms, 3.0) * (0.45 + spark * 0.8));

  vec3 col = diskColor * arms * diskMask * doppler * (1.6 + bass * 0.85);
  col += vec3(0.28, 0.72, 1.0) * photonRing * (0.85 + energy * 0.65);

  // Background starfield distorted by gravity
  vec2 starGrid = floor(lensP * 28.0);
  float starHash = hash21(starGrid);
  if (starHash > 0.962) {
    if (r > eventHorizon * 1.15) {
      vec2 starFrac = fract(lensP * 28.0) - 0.5;
      float starDist = length(starFrac);
      float starTwinkle = 0.5 + 0.5 * sin(t * 3.0 + starHash * 30.0);
      float starBright = (0.018 * starTwinkle + 0.028 * spark) / (starDist * starDist * 60.0 + 0.05);
      col += vec3(0.85, 0.92, 1.0) * starBright;
    }
  }

  // Black hole pitch black core shadow
  float shadow = smoothstep(eventHorizon * 0.85, eventHorizon * 1.05, r);
  col *= shadow;

  // Relativistic polar jet radiance
  float jetY = abs(p.y);
  float jetX = abs(p.x);
  float jet = exp(-jetX * 36.0) * smoothstep(0.18, 1.25, jetY) * (0.15 + 0.85 * bass);
  col += electricCyan * jet * 0.55;

  // Cinematic tone mapping and soft vignette
  col = col / (col + vec3(0.92));
  float vignette = 1.0 - smoothstep(0.55, 1.45, length(p));
  col *= vignette;

  float alpha = clamp(max(col.r, max(col.g, col.b)) * 1.8, 0.0, 1.0);
  // RGBA recto: el motor multiplica por alpha al componer.
  return vec4(clamp(col * f.intensity * f.glow, 0.0, 1.0), alpha);
}

